import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';
import { performOnDemandAccrual } from '@/lib/accrual-helper';

/**
 * Personal Ledger (Khata) API — Reads from Journal Entries (Real Accounting)
 *
 * PRINCIPLE: Personal Ledger is the subsidiary ledger for "Loans Receivable".
 * It is POSTED FROM the Journal / Day Book — just like real accounting.
 *
 * Only journal entry lines that debit or credit the Loans Receivable account
 * (codes 1200 / 1201 / 1210) appear here.
 *
 * Consequence: Processing Fee entries (Dr. Bank / Cr. Processing Fee Income)
 * do NOT appear in the Personal Ledger because they do not touch Loans Receivable.
 *
 * MIRROR RULE:
 *   • Loan has mirror → Receivable belongs to MIRROR company.
 *     Original company does NOT carry this receivable.
 *     Mirror company's journal entry (linked via mirrorLoanId) is the source of truth.
 *   • Loan has no mirror → Original company carries the receivable.
 *
 * CONTROL ACCOUNT:
 *   Loans Receivable (1200) in Trial Balance = SUM of all personal ledger balances.
 *   This is the subsidiary-to-control reconciliation.
 */

// Loans Receivable and Interest Receivable account codes
const LR_CODES = ['1200', '1201', '1210', '1301', '1305', '1302'];

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const customerId = searchParams.get('customerId');
    const loanId     = searchParams.get('loanId');
    const companyId  = searchParams.get('companyId');

    // Run on-demand accruals to ensure ledger is real-time
    await performOnDemandAccrual(companyId);

    if (!customerId && !loanId) {
      return await listCustomersForCompany(companyId);
    }
    if (customerId) {
      return await getPersonalLedger(customerId, companyId);
    }
    if (loanId) {
      return await getSingleLoanLedger(loanId, companyId);
    }

    return NextResponse.json({ success: false, error: 'Missing parameters' }, { status: 400 });

  } catch (error: any) {
    console.error('[Personal Ledger] Error:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to fetch personal ledger', details: error.message },
      { status: 500 }
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Rename "Loans Receivable" → "Loan Given" in all display labels
// ─────────────────────────────────────────────────────────────────────────────
function toLoanGivenLabel(accountName: string, customerName?: string): string {
  const base = accountName.replace(/loans? receivable/gi, 'Loan Given');
  if (customerName && base.toLowerCase().includes('loan given') && !base.includes(customerName)) {
    return `Loan Given — ${customerName}`;
  }
  return base;
}

// ─────────────────────────────────────────────────────────────────────────────
// Get the Loans Receivable account IDs for a company (or all companies)
// Falls back to all-company search if company-specific accounts not found
// (e.g. new company that hasn't been initialized yet)
// ─────────────────────────────────────────────────────────────────────────────
async function getLRAccountIds(companyId: string | null): Promise<string[]> {
  const where: any = { accountCode: { in: LR_CODES } };
  if (companyId) where.companyId = companyId;
  let accounts = await db.chartOfAccount.findMany({ where, select: { id: true } });

  // Fallback: if no accounts found for specific company, search all companies
  if (accounts.length === 0 && companyId) {
    accounts = await db.chartOfAccount.findMany({
      where: { accountCode: { in: LR_CODES } },
      select: { id: true }
    });
  }
  return accounts.map(a => a.id);
}

// ─────────────────────────────────────────────────────────────────────────────
// HELPER: Normalizes name and phone to group/merge duplicate offline/online contacts
// ─────────────────────────────────────────────────────────────────────────────
async function getContactUserMap() {
  const allRegisteredUsers = await db.user.findMany({
    select: { id: true, name: true, phone: true, email: true }
  });
  
  const userMapByContact = new Map<string, { id: string; name: string; phone: string; email: string }>();
  for (const u of allRegisteredUsers) {
    if (u.name && u.phone) {
      const key = `${u.name.trim().toLowerCase()}_${u.phone.trim().replace(/\D/g, '')}`;
      userMapByContact.set(key, {
        id: u.id,
        name: u.name,
        phone: u.phone,
        email: u.email || '',
      });
    }
  }
  return userMapByContact;
}

function getCustomerForContact(
  userMapByContact: Map<string, { id: string; name: string; phone: string; email: string }>,
  name: string | null,
  phone: string | null,
  linkedCustomer?: { id: string; name: string | null; phone: string | null; email: string | null },
  fallbackId?: string
) {
  const cleanName = (name || linkedCustomer?.name || '').trim();
  const cleanPhone = (phone || linkedCustomer?.phone || '').trim();
  
  if (cleanName && cleanPhone) {
    const key = `${cleanName.toLowerCase()}_${cleanPhone.replace(/\D/g, '')}`;
    const registered = userMapByContact.get(key);
    if (registered) {
      return registered;
    }
    
    // Fallback to a consistent synthetic group ID based on name and phone
    return {
      id: `offline_name_${cleanName.toLowerCase()}_${cleanPhone.replace(/\D/g, '')}`,
      name: cleanName,
      phone: cleanPhone,
      email: linkedCustomer?.email || '',
    };
  }
  
  if (linkedCustomer) {
    return {
      id: linkedCustomer.id,
      name: linkedCustomer.name || 'Unknown',
      phone: linkedCustomer.phone || '',
      email: linkedCustomer.email || '',
    };
  }
  
  if (cleanName && fallbackId) {
    return {
      id: fallbackId,
      name: cleanName,
      phone: cleanPhone,
      email: '',
    };
  }
  
  return null;
}

// ─────────────────────────────────────────────────────────────────────────────
// LIST: Customers with their Loans Receivable outstanding balance
// Source: Journal Entry Lines touching Loans Receivable account
// ─────────────────────────────────────────────────────────────────────────────
async function listCustomersForCompany(companyId: string | null) {
  // 1. Get Loans Receivable and Interest account IDs
  const lrAccountIds = await getLRAccountIds(companyId);
  let interestAccounts = await db.chartOfAccount.findMany({
    where: { accountCode: { in: ['4110', '4100', '4001', '4002'] }, ...(companyId ? { companyId } : {}) },
    select: { id: true }
  });
  if (interestAccounts.length === 0 && companyId) {
    interestAccounts = await db.chartOfAccount.findMany({
      where: { accountCode: { in: ['4110', '4100', '4001', '4002'] } },
      select: { id: true }
    });
  }
  const interestAccountIds = interestAccounts.map(a => a.id);
  const allTargetAccountIds = [...lrAccountIds, ...interestAccountIds];

  if (allTargetAccountIds.length === 0) {
    // Fallback: use EMI data if no accounts exist yet
    return listCustomersFallback(companyId);
  }

  // 2. Two-step: get journal entry IDs for this company first, then find lines
  // (Prisma 5 does not support nested relation filters reliably in findMany)
  const journalIds = await db.journalEntry.findMany({
    where: {
      isReversed: false,
      ...(companyId ? { companyId } : {}),
    },
    select: { id: true }
  });
  const journalIdSet = journalIds.map(j => j.id);

  // 2b. Fetch all JournalEntryLines touching LR or Interest accounts within those journals
  const lines = journalIdSet.length > 0
    ? await db.journalEntryLine.findMany({
        where: {
          accountId: { in: allTargetAccountIds },
          journalEntryId: { in: journalIdSet },
        },
        select: {
          accountId:      true,
          debitAmount:    true,
          creditAmount:   true,
          loanId:         true,
          customerId:     true,
          journalEntryId: true,
        }
      })
    : [];

  // If no journal entries found at all, use fallback
  if (lines.length === 0) {
    return listCustomersFallback(companyId);
  }

  // 3. Collect unique loan IDs from lines (some lines may only have customerId)
  const loanIdsFromLines = [...new Set(lines.map(l => l.loanId).filter(Boolean) as string[])];

  // If lines exist but have no loanId attached — journal entries were created without loanId
  // Fall back to EMI-based data which always has loan references
  if (loanIdsFromLines.length === 0) {
    return listCustomersFallback(companyId);
  }

  // 4. Get mirror mappings to apply mirror rule (BOTH online AND offline)
  const mirrorMappings = loanIdsFromLines.length > 0
    ? await db.mirrorLoanMapping.findMany({
        where: { originalLoanId: { in: loanIdsFromLines } }, // includes offline mirrors too
        select: { originalLoanId: true, mirrorCompanyId: true, mirrorLoanId: true }
      })
    : [];
  const mirroredLoanIds    = new Set(mirrorMappings.map(m => m.originalLoanId));
  const mirrorCompanyOfLoan = new Map(mirrorMappings.map(m => [m.originalLoanId, m.mirrorCompanyId]));

  // 4b. Build REVERSE map: mirrorLoanId → originalLoanId
  // This handles the case where a mirror loan record (e.g. C1-PERSONAL-00001) has its own
  // journal entries with loanId = C1_MIRROR_LOAN_ID, causing duplicate customer rows.
  const reverseMirrorMappings = loanIdsFromLines.length > 0
    ? await db.mirrorLoanMapping.findMany({
        where: { mirrorLoanId: { in: loanIdsFromLines } },
        select: { mirrorLoanId: true, originalLoanId: true }
      })
    : [];
  // mirrorLoanId → originalLoanId
  const mirrorToOriginalId = new Map(
    reverseMirrorMappings.filter(m => m.mirrorLoanId).map(m => [m.mirrorLoanId!, m.originalLoanId])
  );

  // 5. Build customer name map from loanId
  const onlineLoans = loanIdsFromLines.length > 0
    ? await db.loanApplication.findMany({
        where: { id: { in: loanIdsFromLines } },
        select: { id: true, customer: { select: { id: true, name: true, phone: true, email: true } } }
      })
    : [];
  const offlineLoans = loanIdsFromLines.length > 0
    ? await db.offlineLoan.findMany({
        where: { id: { in: loanIdsFromLines } },
        select: {
          id: true,
          customerName: true,
          customerPhone: true,
          customerEmail: true,
          customer: { select: { id: true, name: true, phone: true, email: true } }
        }
      })
    : [];

  const userMapByContact = await getContactUserMap();

  const loanToCustomer = new Map<string, { id: string; name: string; phone: string; email: string }>();
  for (const l of onlineLoans) {
    if (l.customer) {
      const cust = getCustomerForContact(userMapByContact, l.customer.name, l.customer.phone, l.customer);
      if (cust) loanToCustomer.set(l.id, cust);
    }
  }
  for (const l of offlineLoans) {
    const cust = getCustomerForContact(
      userMapByContact,
      l.customerName,
      l.customerPhone,
      l.customer || undefined,
      `offline_${l.id}`
    );
    if (cust) {
      loanToCustomer.set(l.id, cust);
    }
  }

  // Propagate customer from original loan to mirror loan record (de-dupe)
  // If a mirror loan ID has its own journal entries but no linked customer, redirect it
  // to the original loan's customer so they merge into one row in byCustomer.
  for (const [mirrorId, originalId] of mirrorToOriginalId) {
    if (!loanToCustomer.has(mirrorId) || loanToCustomer.get(mirrorId)?.id.startsWith('offline_')) {
      // Mirror loan has no customer or only a synthetic one — use original's customer
      const origCustomer = loanToCustomer.get(originalId);
      if (origCustomer) loanToCustomer.set(mirrorId, origCustomer);
    }
  }

  // 6. Also build customer map for lines that have customerId but no loanId
  const customerIdsFromLines = [...new Set(lines.filter(l => !l.loanId && l.customerId).map(l => l.customerId!) )];
  const customersById = customerIdsFromLines.length > 0
    ? await db.user.findMany({
        where: { id: { in: customerIdsFromLines } },
        select: { id: true, name: true, phone: true, email: true }
      })
    : [];
  const customerMap = new Map(customersById.map(c => [c.id, c]));

  // 7. Apply mirror rule and group by customer
  type CustomerAccum = {
    id: string; name: string; phone: string; email: string;
    lrDebits: number; lrCredits: number; interestCredits: number; loans: Set<string>;
    isMirror: boolean;
  };
  const byCustomer = new Map<string, CustomerAccum>();

  for (const line of lines) {
    // Determine if this line should be included for the requested company
    if (line.loanId) {
      if (mirroredLoanIds.has(line.loanId) && companyId) {
        // Has mirror: only include if viewing from the MIRROR company
        const mirrorCo = mirrorCompanyOfLoan.get(line.loanId);
        if (mirrorCo !== companyId) continue; // Skip — original company view
      }
    }

    // Get customer info — if this line belongs to a mirror loan record, redirect to original loan
    let customer: { id: string; name: string; phone: string; email: string } | undefined;
    const effectiveLoanId = line.loanId && mirrorToOriginalId.has(line.loanId)
      ? mirrorToOriginalId.get(line.loanId)!  // use original loan's customer
      : line.loanId;
    if (effectiveLoanId) {
      customer = loanToCustomer.get(effectiveLoanId);
      // Fallback: try the raw loanId too (in case only the mirror loanId has a customer entry)
      if (!customer && line.loanId) customer = loanToCustomer.get(line.loanId);
    } else if (line.customerId) {
      const c = customerMap.get(line.customerId);
      if (c) {
        const cust = getCustomerForContact(userMapByContact, c.name, c.phone, c);
        if (cust) customer = cust;
      }
    }
    if (!customer) continue;

    const isMirror = line.loanId ? (mirroredLoanIds.has(line.loanId) || mirrorToOriginalId.has(line.loanId)) : false;

    if (!byCustomer.has(customer.id)) {
      byCustomer.set(customer.id, {
        id: customer.id, name: customer.name, phone: customer.phone, email: customer.email,
        lrDebits: 0, lrCredits: 0, interestCredits: 0, loans: new Set(),
        isMirror,
      });
    }
    const acc = byCustomer.get(customer.id)!;
    if (lrAccountIds.includes(line.accountId)) {
      acc.lrDebits  += line.debitAmount;
      acc.lrCredits += line.creditAmount;
    } else {
      acc.interestCredits += line.creditAmount;
    }
    if (line.loanId) acc.loans.add(line.loanId);
  }

  const result = [...byCustomer.values()].map(c => ({
    id:               c.id,
    name:             c.name,
    phone:            c.phone,
    email:            c.email,
    totalLoans:       c.loans.size,
    totalOutstanding: Math.max(0, c.lrDebits - c.lrCredits),
    totalPaid:        c.lrCredits + c.interestCredits,
    isMirror:         c.isMirror,
  })).filter(c => c.totalLoans > 0 || c.totalOutstanding > 0);

  result.sort((a, b) => b.totalOutstanding - a.totalOutstanding);

  const totalLoansReceivable = result.reduce((s, c) => s + c.totalOutstanding, 0);

  return NextResponse.json({
    success: true,
    borrowers: result,
    totalLoansReceivable,
    debtorCount: result.filter(c => c.totalOutstanding > 0).length,
    source: 'journal_entries', // indicates data is from real journal entries
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// FALLBACK: Used when no journal entries exist yet (e.g. old data)
// Reads from EMI schedules directly but still excludes processing fee
// ─────────────────────────────────────────────────────────────────────────────
async function listCustomersFallback(companyId: string | null) {
  const userMapByContact = await getContactUserMap();
  const result: any[] = [];
  const seenCustomers = new Map<string, any>();

  const addOrMerge = (customerId: string, entry: any) => {
    const existing = seenCustomers.get(customerId);
    if (existing) {
      existing.totalLoans       += entry.totalLoans;
      existing.totalOutstanding += entry.totalOutstanding;
      existing.totalPaid        += entry.totalPaid;
    } else {
      seenCustomers.set(customerId, entry);
      result.push(entry);
    }
  };

  // ── Fetch all mirror mappings upfront ─────────────────────────────────────
  const allMirrorMappings = await db.mirrorLoanMapping.findMany({
    where: { isOfflineLoan: false },
    select: { originalLoanId: true, mirrorCompanyId: true, mirrorLoanId: true }
  });
  const mirroredOriginalIds = new Set(allMirrorMappings.map(m => m.originalLoanId));
  const mirrorCompanyOfLoan = new Map(allMirrorMappings.map(m => [m.originalLoanId, m.mirrorCompanyId]));
  const calcOutstandingOnline = (emis: { paymentStatus: string; totalAmount: number; paidAmount: number | null }[]) =>
    emis.reduce((s, e) =>
      ['PAID', 'WAIVED', 'INTEREST_ONLY_PAID'].includes(e.paymentStatus)
        ? s : s + (e.totalAmount - (e.paidAmount || 0)), 0);

  const calcOutstandingOffline = (emis: { paymentStatus: string; totalAmount: number; paidAmount: number | null }[]) =>
    emis.reduce((s, e) =>
      ['PAID', 'WAIVED'].includes(e.paymentStatus)
        ? s : s + (e.totalAmount - (e.paidAmount || 0)), 0);

  const calcPaid = (emis: { paidAmount: number | null }[]) =>
    emis.reduce((s, e) => s + (e.paidAmount || 0), 0);

  // ══════════════════════════════════════════════════════════════════
  // STEP 1: Mirror-mapped loans (mirror company view)
  // The original loan belongs to another company — we must look up
  // MirrorLoanMapping explicitly to find what this company "owns".
  // ══════════════════════════════════════════════════════════════════
  if (companyId) {
    // --- Online mirror loans ---
    const onlineMirrorMappings = await db.mirrorLoanMapping.findMany({
      where: { mirrorCompanyId: companyId, isOfflineLoan: false },
      select: { originalLoanId: true, mirrorLoanId: true }
    });

    for (const mapping of onlineMirrorMappings) {
      // Prefer mirror loan record (has its own EMI schedule) if it exists
      const loanId = mapping.mirrorLoanId || mapping.originalLoanId;
      const loan = await db.loanApplication.findUnique({
        where: { id: loanId },
        include: {
          customer: { select: { id: true, name: true, phone: true, email: true } },
          emiSchedules: { select: { paymentStatus: true, totalAmount: true, paidAmount: true } }
        }
      });
      if (!loan?.customer) {
        // Mirror loan has no direct customer — fall back to original loan's customer
        if (mapping.mirrorLoanId && mapping.mirrorLoanId !== mapping.originalLoanId) {
          const orig = await db.loanApplication.findUnique({
            where: { id: mapping.originalLoanId },
            include: {
              customer: { select: { id: true, name: true, phone: true, email: true } },
              emiSchedules: { select: { paymentStatus: true, totalAmount: true, paidAmount: true } }
            }
          });
          if (!orig?.customer) continue;
          const cust = getCustomerForContact(userMapByContact, orig.customer.name, orig.customer.phone, orig.customer);
          if (cust) {
            addOrMerge(cust.id, {
              id: cust.id, name: cust.name,
              phone: cust.phone, email: cust.email,
              totalLoans: 1,
              totalOutstanding: calcOutstandingOnline(orig.emiSchedules),
              totalPaid: calcPaid(orig.emiSchedules),
              isMirror: true,
            });
          }
        }
        continue;
      }
      const cust = getCustomerForContact(userMapByContact, loan.customer.name, loan.customer.phone, loan.customer);
      if (cust) {
        addOrMerge(cust.id, {
          id: cust.id, name: cust.name,
          phone: cust.phone, email: cust.email,
          totalLoans: 1,
          totalOutstanding: calcOutstandingOnline(loan.emiSchedules),
          totalPaid: calcPaid(loan.emiSchedules),
          isMirror: true,
        });
      }
    }

    // --- Offline mirror loans ---
    const offlineMirrorMappings = await db.mirrorLoanMapping.findMany({
      where: { mirrorCompanyId: companyId, isOfflineLoan: true },
      select: { originalLoanId: true, mirrorLoanId: true }
    });

    for (const mapping of offlineMirrorMappings) {
      const loanId = mapping.mirrorLoanId || mapping.originalLoanId;
      const loan = await db.offlineLoan.findUnique({
        where: { id: loanId },
        include: {
          customer: { select: { id: true, name: true, phone: true, email: true } },
          emis: { select: { paymentStatus: true, totalAmount: true, paidAmount: true } }
        }
      });
      if (!loan) continue;
      const outstanding = calcOutstandingOffline(loan.emis);
      const totalPaid   = calcPaid(loan.emis);
      const cust = getCustomerForContact(
        userMapByContact,
        loan.customerName,
        loan.customerPhone,
        loan.customer || undefined,
        `offline_${loan.id}`
      );
      if (cust) {
        addOrMerge(cust.id, {
          id: cust.id,
          name: cust.name,
          phone: cust.phone,
          email: cust.email || loan.customerEmail || '',
          totalLoans: 1, totalOutstanding: outstanding, totalPaid, isMirror: true,
        });
      }
    }
  }

  // ══════════════════════════════════════════════════════════════════
  // STEP 2: Direct (non-mirrored) loans for this company
  // ══════════════════════════════════════════════════════════════════

  // All online mirror-original IDs globally (to exclude from direct view)
  const allMirroredOnlineIds = new Set(
    (await db.mirrorLoanMapping.findMany({
      where: { isOfflineLoan: false },
      select: { originalLoanId: true }
    })).map(m => m.originalLoanId)
  );

  const onlineWhere: any = {
    status: { in: ['ACTIVE', 'DISBURSED', 'CLOSED', 'ACTIVE_INTEREST_ONLY', 'FINAL_APPROVED'] },
  };
  if (companyId) onlineWhere.companyId = companyId;
  // Exclude originals that have mirrors (mirror loan record handles those above)
  if (allMirroredOnlineIds.size > 0) onlineWhere.id = { notIn: [...allMirroredOnlineIds] };

  const onlineLoans = await db.loanApplication.findMany({
    where: onlineWhere,
    include: {
      customer: { select: { id: true, name: true, phone: true, email: true } },
      emiSchedules: { select: { paymentStatus: true, totalAmount: true, paidAmount: true } }
    }
  });

  for (const loan of onlineLoans) {
    if (!loan.customer) continue;
    const cust = getCustomerForContact(userMapByContact, loan.customer.name, loan.customer.phone, loan.customer);
    if (cust) {
      addOrMerge(cust.id, {
        id: cust.id,
        name: cust.name,
        phone: cust.phone,
        email: cust.email,
        totalLoans: 1,
        totalOutstanding: calcOutstandingOnline(loan.emiSchedules),
        totalPaid: calcPaid(loan.emiSchedules),
        isMirror: false,
      });
    }
  }

  // All offline mirror-original IDs globally
  const allMirroredOfflineIds = new Set(
    (await db.mirrorLoanMapping.findMany({
      where: { isOfflineLoan: true },
      select: { originalLoanId: true }
    })).map(m => m.originalLoanId)
  );

  const offlineWhere: any = {
    status: { in: ['ACTIVE', 'INTEREST_ONLY', 'CLOSED'] },
  };
  if (companyId) offlineWhere.companyId = companyId;
  // Exclude offline originals that have mirrors (handled above via mirrorMappings)
  if (allMirroredOfflineIds.size > 0) offlineWhere.id = { notIn: [...allMirroredOfflineIds] };

  const offlineLoans = await db.offlineLoan.findMany({
    where: offlineWhere,
    include: {
      customer: { select: { id: true, name: true, phone: true, email: true } },
      emis: { select: { paymentStatus: true, totalAmount: true, paidAmount: true } }
    }
  });

  for (const loan of offlineLoans) {
    const outstanding = loan.emis.reduce((s, e) =>
      ['PAID', 'WAIVED'].includes(e.paymentStatus)
        ? s : s + (e.totalAmount - (e.paidAmount || 0)), 0);
    const totalPaid = loan.emis.reduce((s, e) => s + (e.paidAmount || 0), 0);

    const cust = getCustomerForContact(
      userMapByContact,
      loan.customerName,
      loan.customerPhone,
      loan.customer || undefined,
      `offline_${loan.id}`
    );
    if (cust) {
      addOrMerge(cust.id, {
        id: cust.id,
        name: cust.name,
        phone: cust.phone,
        email: cust.email || loan.customerEmail || '',
        totalLoans: 1, totalOutstanding: outstanding, totalPaid, isMirror: false,
      });
    }
  }

  result.sort((a, b) => b.totalOutstanding - a.totalOutstanding);
  const totalLoansReceivable = result.reduce((s, c) => s + c.totalOutstanding, 0);

  return NextResponse.json({
    success: true,
    borrowers: result,
    totalLoansReceivable,
    debtorCount: result.filter(c => c.totalOutstanding > 0).length,
    source: 'emi_fallback',
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// PERSONAL LEDGER for one customer — posted from Journal Entries
// ─────────────────────────────────────────────────────────────────────────────
async function getPersonalLedger(customerId: string, companyId: string | null) {
  // Handle synthetic IDs for offline loans without linked user accounts
  // Format 1 (old): 'offline_{loanId}'  — single loan
  // Format 2 (new): 'offline_name_{name}_{phone}' — name+phone group
  const isSyntheticId = customerId.startsWith('offline_');
  const isNameGroupId = customerId.startsWith('offline_name_');
  const syntheticLoanId = (isSyntheticId && !isNameGroupId) ? customerId.replace('offline_', '') : null;

  // Parse name+phone from the group key
  let groupName: string | null = null;
  let groupPhone: string | null = null;
  if (isNameGroupId) {
    // format: offline_name_{lowercaseName}_{phone}
    const parts = customerId.replace('offline_name_', '').split('_');
    // phone is the last part; name is everything else joined back
    groupPhone = parts[parts.length - 1];
    groupName  = parts.slice(0, parts.length - 1).join(' ');
  }

  let customer: { id: string; name: string | null; phone: string | null; email: string | null; address?: string | null } | null = null;

  if (isNameGroupId && groupName) {
    // Fetch customer info from any offline loan with matching name (case-insensitive)
    const sampleLoan = await db.offlineLoan.findFirst({
      where: { customerName: groupName },
      select: { customerName: true, customerPhone: true, customerEmail: true }
    });
    if (sampleLoan) {
      customer = { id: customerId, name: sampleLoan.customerName || groupName, phone: sampleLoan.customerPhone || groupPhone || '', email: sampleLoan.customerEmail || '' };
    } else {
      customer = { id: customerId, name: groupName, phone: groupPhone || '', email: '' };
    }
  } else if (isSyntheticId && syntheticLoanId) {
    // Fetch customer info directly from the offline loan (old format)
    const offlineLoan = await db.offlineLoan.findUnique({
      where: { id: syntheticLoanId },
      select: { customerName: true, customerPhone: true, customerEmail: true }
    });
    if (offlineLoan) {
      customer = { id: customerId, name: offlineLoan.customerName || 'Unknown', phone: offlineLoan.customerPhone || '', email: offlineLoan.customerEmail || '' };
    }
  } else {
    customer = await db.user.findUnique({
      where: { id: customerId },
      select: { id: true, name: true, phone: true, email: true, address: true }
    });
  }

  // Get all loans for this customer
  const allOnlineLoans = isSyntheticId ? [] : await db.loanApplication.findMany({
    where: {
      customerId,
      status: {
        notIn: ['REJECTED_BY_SA', 'REJECTED_BY_COMPANY', 'REJECTED_FINAL', 'SESSION_REJECTED']
      }
    },
    select: {
      id: true, applicationNo: true, status: true, companyId: true,
      requestedAmount: true, disbursedAt: true, closedAt: true,
      sessionForm: { select: { approvedAmount: true, interestRate: true, tenure: true, processingFee: true } },
      company: { select: { id: true, name: true } },
      emiSchedules: { select: { id: true, installmentNumber: true, dueDate: true, paidDate: true, paidAmount: true, interestAmount: true, outstandingPrincipal: true, paidPrincipal: true, paidInterest: true } }
    }
  });

  // For name-grouped IDs: fetch ALL offline loans with matching name
  // For old single-loan syntheticId: fetch just that one loan
  // For real user ID: fetch by customerId field
  let allOfflineLoans: any[];
  if (isNameGroupId && groupName) {
    const nameWhere: any = {
      customerName: groupName,
      status: { in: ['ACTIVE', 'INTEREST_ONLY', 'CLOSED'] },
    };
    if (companyId) nameWhere.companyId = companyId;
    allOfflineLoans = await db.offlineLoan.findMany({
      where: nameWhere,
      select: {
        id: true, loanNumber: true, status: true, companyId: true,
        loanAmount: true, disbursementDate: true, interestRate: true, tenure: true,
        customerName: true, customerPhone: true, customerEmail: true,
        closedAt: true,
        company: { select: { id: true, name: true } },
        emis: { select: { id: true, installmentNumber: true, dueDate: true, paidDate: true, paidAmount: true, interestAmount: true, outstandingPrincipal: true, paidPrincipal: true, paidInterest: true } }
      }
    });
  } else if (isSyntheticId && syntheticLoanId) {
    allOfflineLoans = await db.offlineLoan.findMany({
      where: { id: syntheticLoanId },
      select: {
        id: true, loanNumber: true, status: true, companyId: true,
        loanAmount: true, disbursementDate: true, interestRate: true, tenure: true,
        customerName: true, customerPhone: true, customerEmail: true,
        closedAt: true,
        company: { select: { id: true, name: true } },
        emis: { select: { id: true, installmentNumber: true, dueDate: true, paidDate: true, paidAmount: true, interestAmount: true, outstandingPrincipal: true, paidPrincipal: true, paidInterest: true } }
      }
    });
  } else {
    allOfflineLoans = await db.offlineLoan.findMany({
      where: { customerId, status: { in: ['ACTIVE', 'INTEREST_ONLY', 'CLOSED'] } },
      select: {
        id: true, loanNumber: true, status: true, companyId: true,
        loanAmount: true, disbursementDate: true, interestRate: true, tenure: true,
        customerName: true, customerPhone: true, customerEmail: true,
        closedAt: true,
        company: { select: { id: true, name: true } },
        emis: { select: { id: true, installmentNumber: true, dueDate: true, paidDate: true, paidAmount: true, interestAmount: true, outstandingPrincipal: true, paidPrincipal: true, paidInterest: true } }
      }
    });
  }


  // Mirror rule: which online loans are mirrored ORIGINALS?
  const onlineLoanIds = allOnlineLoans.map(l => l.id);
  const mirrorMappings = onlineLoanIds.length > 0
    ? await db.mirrorLoanMapping.findMany({
        where: { originalLoanId: { in: onlineLoanIds }, isOfflineLoan: false },
        select: { originalLoanId: true, mirrorLoanId: true, mirrorCompanyId: true, mirrorInterestRate: true }
      })
    : [];

  // Build a map from mirrorLoanId → correct mirror principal (from the mirror EMI schedule EMI #1)
  // The mirror LoanApplication reuses the original loan's requestedAmount — so we cannot trust
  // sessionForm.approvedAmount for the disbursement row. Instead, derive it from the first EMI's
  // outstandingPrincipal, which is set at mirror-loan creation time using the mirror-specific principal.
  const mirrorLoanPrincipalMap = new Map<string, number>();
  const mirrorOnlineLoanIds = mirrorMappings.map(m => m.mirrorLoanId).filter(Boolean) as string[];
  if (mirrorOnlineLoanIds.length > 0) {
    const firstMirrorEmis = await db.eMISchedule.findMany({
      where: { loanApplicationId: { in: mirrorOnlineLoanIds }, installmentNumber: 1 },
      select: { loanApplicationId: true, outstandingPrincipal: true, principalAmount: true }
    });
    for (const emi of firstMirrorEmis) {
      const principal = Number(emi.outstandingPrincipal || emi.principalAmount || 0);
      if (principal > 0) mirrorLoanPrincipalMap.set(emi.loanApplicationId, principal);
    }
  }
  const mirroredIds    = new Set(mirrorMappings.map(m => m.originalLoanId));
  const mirrorLoanIds  = new Set(mirrorMappings.map(m => m.mirrorLoanId).filter(Boolean) as string[]);

  // ── When viewing from mirror company: also fetch mirror loans via MirrorLoanMapping ──
  // The mirror LoanApplication might not have the same customerId, so we fetch explicitly.
  let extraMirrorOnlineLoans: any[] = [];
  
  // Find all mappings matching the company filter (or all if companyId is null)
  const relevantMirrorMappings = mirrorMappings.filter(m => !companyId || m.mirrorCompanyId === companyId);
  
  const customerMirrorMappings = relevantMirrorMappings.filter(m => m.mirrorLoanId);
  for (const mapping of customerMirrorMappings) {
    if (!allOnlineLoans.find(l => l.id === mapping.mirrorLoanId)) {
      const mirrorLoan = await db.loanApplication.findUnique({
        where: { id: mapping.mirrorLoanId! },
        select: {
          id: true, applicationNo: true, status: true, companyId: true,
          requestedAmount: true, disbursedAt: true, closedAt: true,
          sessionForm: { select: { approvedAmount: true, interestRate: true, tenure: true } },
          company: { select: { id: true, name: true } },
          emiSchedules: { select: { id: true, installmentNumber: true, dueDate: true, paidDate: true, paidAmount: true, interestAmount: true, outstandingPrincipal: true, paidPrincipal: true, paidInterest: true } }
        }
      });
      if (mirrorLoan) extraMirrorOnlineLoans.push({ ...mirrorLoan, _isMirrorRecord: true });
    }
  }
  
  // Also check: mirror company but NO mirrorLoanId — use original loan data with mirror flag
  const nullMirrorMappings = relevantMirrorMappings.filter(m => !m.mirrorLoanId);
  for (const mapping of nullMirrorMappings) {
    const origLoan = allOnlineLoans.find(l => l.id === mapping.originalLoanId);
    if (origLoan) extraMirrorOnlineLoans.push({ ...origLoan, _isMirrorRecord: true });
  }

  // Filter: hide originals that have mirrors; show mirror loan records
  const validOnlineLoans = [
    // From customer's own loans — exclude mirrored originals unless viewing original company
    ...allOnlineLoans.filter(l => {
      if (mirroredIds.has(l.id)) {
        // If viewing the original company, SHOW the original!
        if (companyId && l.companyId === companyId) return true;
        // Otherwise (All Companies or Mirror Company), hide the original (we show mirror via extraMirrorOnlineLoans)
        return false; 
      }
      if (mirrorLoanIds.has(l.id)) return !companyId || l.companyId === companyId;
      return !companyId || l.companyId === companyId;
    }),
    // Plus any extra mirror loans fetched above
    ...extraMirrorOnlineLoans,
  ];

  // For offline: allOfflineLoans are the customer's actual loans (by customerId)
  // If a loan is mirrored, show it for the mirror company; if not mirrored, show for its own company
  const offlineMirrorMappings = await db.mirrorLoanMapping.findMany({
    where: { isOfflineLoan: true },
    select: { originalLoanId: true, mirrorCompanyId: true, mirrorInterestRate: true, mirrorLoanId: true }
  });
  const mirroredOfflineIds = new Set(offlineMirrorMappings.map(m => m.originalLoanId));
  const mirrorOfflineLoanIds = new Set(offlineMirrorMappings.map(m => m.mirrorLoanId).filter(Boolean) as string[]);
  const offlineMirrorCoMap = new Map(offlineMirrorMappings.map(m => [m.originalLoanId, m.mirrorCompanyId]));
  const offlineMirrorRateMap = new Map(offlineMirrorMappings.map(m => [m.originalLoanId, m.mirrorInterestRate]));

  // Fetch any mirror offline loans explicitly if they are not in allOfflineLoans
  let extraMirrorOfflineLoans: any[] = [];
  if (companyId) {
    const customerOfflineLoanIds = new Set(allOfflineLoans.map(l => l.id));
    const customerOfflineMirrorMappings = offlineMirrorMappings.filter(m => 
      m.mirrorCompanyId === companyId && 
      m.mirrorLoanId && 
      (customerOfflineLoanIds.has(m.originalLoanId) || customerOfflineLoanIds.has(m.mirrorLoanId))
    );
    for (const mapping of customerOfflineMirrorMappings) {
      if (!allOfflineLoans.find(l => l.id === mapping.mirrorLoanId)) {
        const mirrorLoan = await db.offlineLoan.findUnique({
          where: { id: mapping.mirrorLoanId! },
          include: {
            company: { select: { id: true, name: true } },
            emis: { select: { id: true, installmentNumber: true, dueDate: true, paymentStatus: true, paidDate: true, paidAmount: true, interestAmount: true, outstandingPrincipal: true, paidPrincipal: true, paidInterest: true } }
          }
        });
        if (mirrorLoan) extraMirrorOfflineLoans.push(mirrorLoan);
      }
    }
  }

  const validOfflineLoans = [
    ...allOfflineLoans.filter(l => {
      if (!companyId) return true;
      
      // If it's the original loan of a mirrored pair
      if (mirroredOfflineIds.has(l.id)) {
        // Show if viewing the original company.
        // If viewing the mirror company, hide it because the mirror loan record (MR-...) will represent it.
        return l.companyId === companyId;
      }
      
      // If it's the mirror loan of a mirrored pair
      const mapping = offlineMirrorMappings.find(m => m.mirrorLoanId === l.id);
      if (mapping) {
        // ONLY show it if we are viewing the mirror company
        return mapping.mirrorCompanyId === companyId;
      }
      
      // Default: show it if it belongs to the company
      return l.companyId === companyId;
    }),
    ...extraMirrorOfflineLoans
  ];

  const validLoanIds = [
    ...validOnlineLoans.map(l => l.id),
    ...validOfflineLoans.map(l => l.id),
  ];

  if (validLoanIds.length === 0) {
    // Last resort: use fallback which has mirror-aware logic
    return getPersonalLedgerFallback(customerId, companyId, customer, [], allOfflineLoans as any[], mirroredIds);
  }


  // ── Get Loans Receivable and Interest Income account IDs ─────────────────
  const lrAccountIds = await getLRAccountIds(companyId);
  let interestAccounts = await db.chartOfAccount.findMany({
    where: { accountCode: { in: ['4110', '4100', '4001', '4002'] }, ...(companyId ? { companyId } : {}) },
    select: { id: true }
  });
  if (interestAccounts.length === 0 && companyId) {
    interestAccounts = await db.chartOfAccount.findMany({
      where: { accountCode: { in: ['4110', '4100', '4001', '4002'] } },
      select: { id: true }
    });
  }
  const interestAccountIds = interestAccounts.map(a => a.id);
  const allTargetAccountIds = [...lrAccountIds, ...interestAccountIds];

  // Map original online/offline loan IDs to their mirror IDs to correctly group cross-company entries
  const originalToMirrorLoanId = new Map<string, string>();
  const queryLoanIds = [...validLoanIds];
  
  if (companyId) {
    // Online mapping
    for (const m of relevantMirrorMappings) {
      if (m.mirrorLoanId && validLoanIds.includes(m.mirrorLoanId)) {
        originalToMirrorLoanId.set(m.originalLoanId, m.mirrorLoanId);
        queryLoanIds.push(m.originalLoanId);
      }
    }
    // Offline mapping
    for (const m of offlineMirrorMappings) {
      if (m.mirrorLoanId && validLoanIds.includes(m.mirrorLoanId)) {
        originalToMirrorLoanId.set(m.originalLoanId, m.mirrorLoanId);
        queryLoanIds.push(m.originalLoanId);
      }
    }
  }

  // Fetch installment numbers for payments and offline EMIs to map je.referenceId to emiNumber
  const paymentToEmiNumber = new Map<string, number>();
  const offlineEmiIdToNumber = new Map<string, number>();

  if (queryLoanIds.length > 0) {
    const paymentsForLedger = await db.payment.findMany({
      where: { loanApplicationId: { in: queryLoanIds } },
      select: { id: true, emiSchedule: { select: { installmentNumber: true } } }
    });
    for (const p of paymentsForLedger) {
      if (p.emiSchedule?.installmentNumber) {
        paymentToEmiNumber.set(p.id, p.emiSchedule.installmentNumber);
      }
    }

    const offlineEmisForLedger = await db.offlineLoanEMI.findMany({
      where: { offlineLoanId: { in: queryLoanIds } },
      select: { id: true, installmentNumber: true }
    });
    for (const e of offlineEmisForLedger) {
      offlineEmiIdToNumber.set(e.id, e.installmentNumber);
    }
  }

  // ── Fetch Journal Entries that have a line touching LR or Interest for these loans ────
  // This is the "posting from journal to personal ledger" step
  let journalEntries: any[] = [];
  if (allTargetAccountIds.length > 0 && queryLoanIds.length > 0) {
    journalEntries = await db.journalEntry.findMany({
      where: {
        isReversed: false,
        ...(companyId ? { companyId } : {}),
        lines: {
          some: {
            accountId: { in: allTargetAccountIds },
            loanId: { in: queryLoanIds },
          }
        }
      },
      include: {
        lines: {
          include: {
            account: { select: { id: true, accountCode: true, accountName: true } }
          }
        }
      },
      orderBy: { entryDate: 'asc' }
    });

    const pfQueryReferenceIds = queryLoanIds.flatMap(lid => [
      lid,
      `${lid}-PF`,
      `${lid}-PF-JE`,
      `${lid}-MIR-PF`,
      `${lid}-MIR-PF-JE`
    ]);

    // ── ALWAYS fetch INTEREST_ACCRUAL and INTEREST_RECLASSIFICATION entries by loanId ──
    // These entries must be permanently visible even after EMI is paid.
    // IMPORTANT: Do NOT filter by companyId here. For mirror loans, accruals are recorded
    // in the ORIGINAL company (e.g. C3/PD RANGANI) but the personal ledger is viewed from
    // the MIRROR company context (e.g. C2/MM). The loanId filter alone is sufficient and
    // correct — it uniquely identifies entries for the right loans across all companies.
    // We also include processing fee entries matching by their specific referenceId formats.
    const accrualEntries = await db.journalEntry.findMany({
      where: {
        isReversed: false,
        referenceType: { in: ['INTEREST_ACCRUAL', 'INTEREST_RECLASSIFICATION', 'PROCESSING_FEE_ACCRUAL', 'PROCESSING_FEE_COLLECTION', 'PROCESSING_FEE'] },
        OR: [
          {
            lines: {
              some: {
                loanId: { in: queryLoanIds },
              }
            }
          },
          {
            referenceId: { in: pfQueryReferenceIds }
          }
        ]
      },
      include: {
        lines: {
          include: {
            account: { select: { id: true, accountCode: true, accountName: true } }
          }
        }
      },
      orderBy: { entryDate: 'asc' }
    });

    // Merge accrual entries — avoid duplicates by ID
    const seenJEIds = new Set(journalEntries.map((je: any) => je.id));
    for (const ae of accrualEntries) {
      if (!seenJEIds.has(ae.id)) {
        journalEntries.push(ae);
        seenJEIds.add(ae.id);
      }
    }

    // ── FALLBACK: also find PROCESSING_FEE_COLLECTION / PROCESSING_FEE_ACCRUAL by referenceId ──
    // Old JEs created before the loanId-tagging fix have NO loanId on their lines.
    // For those, we match by referenceId = loanId (the standard pattern for processing fee JEs).
    // This ensures existing data in DB still shows in Personal Ledger without a DB migration.
    const pfFallbackEntries = await db.journalEntry.findMany({
      where: {
        isReversed: false,
        referenceType: { in: ['PROCESSING_FEE_COLLECTION', 'PROCESSING_FEE_ACCRUAL'] },
        referenceId:   { in: pfQueryReferenceIds },
        id: { notIn: [...seenJEIds] },
      },
      include: {
        lines: {
          include: {
            account: { select: { id: true, accountCode: true, accountName: true } }
          }
        }
      },
      orderBy: { entryDate: 'asc' }
    });
    for (const pfe of pfFallbackEntries) {
      if (!seenJEIds.has(pfe.id)) {
        journalEntries.push(pfe);
        seenJEIds.add(pfe.id);
      }
    }
    const ENTRY_ORDER: Record<string, number> = {
      PROCESSING_FEE_ACCRUAL: 1,
      PROCESSING_FEE_COLLECTION: 2, PROCESSING_FEE: 2,
      LOAN_DISBURSEMENT: 3, MIRROR_LOAN_DISBURSEMENT: 3,
      INTEREST_ACCRUAL: 4, INTEREST_RECLASSIFICATION: 4,
      EMI_PAYMENT: 5, MIRROR_EMI_PAYMENT: 5,
      INTEREST_ONLY_PAYMENT: 5,
      PARTIAL_EMI_PAYMENT: 5,
      PRINCIPAL_ONLY_PAYMENT: 6,
      OFFLINE_LOAN_FORECLOSURE: 7, LOAN_FORECLOSURE: 7, LOSS_WRITE_OFF: 7,
    };
    journalEntries.sort((a: any, b: any) => {
      const dateA = new Date(a.entryDate);
      const dateB = new Date(b.entryDate);

      const isSameDay = dateA.getFullYear() === dateB.getFullYear() &&
                        dateA.getMonth() === dateB.getMonth() &&
                        dateA.getDate() === dateB.getDate();

      if (isSameDay) {
        const entryA = a.entryNumber;
        const entryB = b.entryNumber;
        if (entryA && entryB && entryA.startsWith('JE') && entryB.startsWith('JE') && entryA !== entryB) {
          const cmp = entryA.localeCompare(entryB, undefined, { numeric: true });
          if (cmp !== 0) return cmp;
        }
      }

      const timeA = dateA.getTime();
      const timeB = dateB.getTime();
      if (timeA !== timeB) {
        return timeA - timeB;
      }

      if (a.entryNumber && b.entryNumber && a.entryNumber.startsWith('JE') && b.entryNumber.startsWith('JE') && a.entryNumber !== b.entryNumber) {
        const cmp = a.entryNumber.localeCompare(b.entryNumber, undefined, { numeric: true });
        if (cmp !== 0) return cmp;
      }

      const createA = a.createdAt ? new Date(a.createdAt).getTime() : 0;
      const createB = b.createdAt ? new Date(b.createdAt).getTime() : 0;
      if (createA !== createB) {
        return createA - createB;
      }

      const emiA = a.emiNumber;
      const emiB = b.emiNumber;
      if (emiA !== undefined && emiB !== undefined && emiA !== emiB) {
        return emiA - emiB;
      }

      const oA = ENTRY_ORDER[a.referenceType] ?? 9;
      const oB = ENTRY_ORDER[b.referenceType] ?? 9;
      if (oA !== oB) return oA - oB;

      const idA = a.id || '';
      const idB = b.id || '';
      return idA.localeCompare(idB);
    });
  }

  // ── Fall back to EMI-based entries if no journal entries found ─────────────
  if (journalEntries.length === 0) {
    return getPersonalLedgerFallback(customerId, companyId, customer, validOnlineLoans, validOfflineLoans, mirroredIds);
  }

  // Build a map of counterpart EMI IDs for mirror/original loans to correctly reconcile accruals
  const emiCounterpartMap = new Map<string, string>();
  
  // Offline counterpart mapping
  const displayedOfflineLoanIds = validOfflineLoans.map(l => l.id);
  const allOfflineLoanIdsInMappings = new Set<string>();
  for (const m of offlineMirrorMappings) {
    if (m.mirrorLoanId && (displayedOfflineLoanIds.includes(m.mirrorLoanId) || displayedOfflineLoanIds.includes(m.originalLoanId))) {
      allOfflineLoanIdsInMappings.add(m.originalLoanId);
      allOfflineLoanIdsInMappings.add(m.mirrorLoanId);
    }
  }

  const counterpartOfflineEmis = allOfflineLoanIdsInMappings.size > 0
    ? await db.offlineLoanEMI.findMany({
        where: { offlineLoanId: { in: Array.from(allOfflineLoanIdsInMappings) } },
        select: { id: true, installmentNumber: true, offlineLoanId: true }
      })
    : [];

  const offlineEmisByLoanId = new Map<string, typeof counterpartOfflineEmis>();
  for (const e of counterpartOfflineEmis) {
    if (!offlineEmisByLoanId.has(e.offlineLoanId)) offlineEmisByLoanId.set(e.offlineLoanId, []);
    offlineEmisByLoanId.get(e.offlineLoanId)!.push(e);
  }

  for (const m of offlineMirrorMappings) {
    if (!m.mirrorLoanId) continue;
    const origEmis = offlineEmisByLoanId.get(m.originalLoanId) || [];
    const mirrorEmis = offlineEmisByLoanId.get(m.mirrorLoanId) || [];
    
    for (const oEmi of origEmis) {
      const mEmi = mirrorEmis.find(e => e.installmentNumber === oEmi.installmentNumber);
      if (mEmi) {
        emiCounterpartMap.set(oEmi.id, mEmi.id);
        emiCounterpartMap.set(mEmi.id, oEmi.id);
      }
    }
  }

  // Online counterpart mapping
  const displayedOnlineLoanIds = validOnlineLoans.map(l => l.id);
  const allOnlineLoanIdsInMappings = new Set<string>();
  for (const m of relevantMirrorMappings) {
    if (m.mirrorLoanId && (displayedOnlineLoanIds.includes(m.mirrorLoanId) || displayedOnlineLoanIds.includes(m.originalLoanId))) {
      allOnlineLoanIdsInMappings.add(m.originalLoanId);
      allOnlineLoanIdsInMappings.add(m.mirrorLoanId);
    }
  }

  const counterpartOnlineEmis = allOnlineLoanIdsInMappings.size > 0
    ? await db.eMISchedule.findMany({
        where: { loanApplicationId: { in: Array.from(allOnlineLoanIdsInMappings) } },
        select: { id: true, installmentNumber: true, loanApplicationId: true }
      })
    : [];

  const onlineEmisByLoanId = new Map<string, typeof counterpartOnlineEmis>();
  for (const e of counterpartOnlineEmis) {
    if (!onlineEmisByLoanId.has(e.loanApplicationId)) onlineEmisByLoanId.set(e.loanApplicationId, []);
    onlineEmisByLoanId.get(e.loanApplicationId)!.push(e);
  }

  for (const m of relevantMirrorMappings) {
    if (!m.mirrorLoanId) continue;
    const origEmis = onlineEmisByLoanId.get(m.originalLoanId) || [];
    const mirrorEmis = onlineEmisByLoanId.get(m.mirrorLoanId) || [];
    
    for (const oEmi of origEmis) {
      const mEmi = mirrorEmis.find(e => e.installmentNumber === oEmi.installmentNumber);
      if (mEmi) {
        emiCounterpartMap.set(oEmi.id, mEmi.id);
        emiCounterpartMap.set(mEmi.id, oEmi.id);
      }
    }
  }

  // ── Build per-loan statements from journal entries ─────────────────────────
  const loanDataMap = new Map<string, { loanNumber: string; loanType: string; loanAmount: number; interestRate: number; tenure: number; status: string; disbursementDate: any; closedAt?: any; isMirror: boolean; companyName: string; mirrorInterestRate?: number; emis?: any[]; emiSchedules?: any[] }>();
  for (const l of validOnlineLoans) {
    const isMirrorRecord = mirroredIds.has(l.id) ? false : (mirrorLoanPrincipalMap.has(l.id) || (l as any)._isMirrorRecord);
    // For mirror loan records: use the principal from the mirror EMI schedule (EMI #1 outstandingPrincipal)
    // rather than the loan application's requestedAmount (which copies the original loan amount).
    const mirrorPrincipal = isMirrorRecord ? mirrorLoanPrincipalMap.get(l.id) : undefined;
    loanDataMap.set(l.id, {
      loanNumber: l.applicationNo,
      loanType: 'ONLINE',
      loanAmount: mirrorPrincipal ?? (l.sessionForm?.approvedAmount || l.requestedAmount || 0),
      interestRate: l.sessionForm?.interestRate || 0,
      tenure: l.sessionForm?.tenure || 0,
      status: l.status,
      disbursementDate: l.disbursedAt,
      closedAt: l.closedAt,
      isMirror: isMirrorRecord,
      companyName: l.company?.name || '',
      emiSchedules: l.emiSchedules,
    });
  }
  for (const l of validOfflineLoans) {
    const isOfflineMirror = companyId ? offlineMirrorCoMap.get(l.id) === companyId : false;
    loanDataMap.set(l.id, {
      loanNumber: l.loanNumber,
      loanType: 'OFFLINE',
      loanAmount: l.loanAmount,
      interestRate: l.interestRate || 0,
      tenure: l.tenure || 0,
      status: l.status,
      disbursementDate: l.disbursementDate,
      closedAt: l.closedAt,
      isMirror: isOfflineMirror,
      mirrorInterestRate: isOfflineMirror ? offlineMirrorRateMap.get(l.id) : undefined,
      companyName: l.company?.name || '',
      emis: l.emis,
    });
  }

  // Group journal entries by loanId
  const entriesByLoan = new Map<string, any[]>();
  for (const je of journalEntries) {
    // Find which loanId(s) this entry touches via its LR or Interest lines
    // For accrual/fee entries, their account IDs won't necessarily be in allTargetAccountIds (especially if cross-company).
    const isAccrualOrPF = [
      'INTEREST_ACCRUAL',
      'INTEREST_RECLASSIFICATION',
      'PROCESSING_FEE_ACCRUAL',
      'PROCESSING_FEE_COLLECTION',
      'PROCESSING_FEE'
    ].includes(je.referenceType);
    
    const rawLoanIds = je.lines
        .filter((l: any) => (isAccrualOrPF || allTargetAccountIds.includes(l.accountId)) && l.loanId)
        .map((l: any) => String(l.loanId));
        
    let loanIdsInEntry: string[] = Array.from(new Set<string>(rawLoanIds));

    // Fallback for Processing Fee JEs where NO line has a loanId (old DB entries before loanId-tagging fix):
    // Use the JE's referenceId (with suffixes removed) as the loan identifier.
    if (loanIdsInEntry.length === 0 && isAccrualOrPF && je.referenceId) {
      const cleanRefId = je.referenceId
        .replace(/-MIR-PF-JE$/i, '')
        .replace(/-PF-JE$/i, '')
        .replace(/-MIR-PF$/i, '')
        .replace(/-PF$/i, '');
      if (queryLoanIds.includes(cleanRefId)) {
        loanIdsInEntry = [cleanRefId];
      }
    }

    for (let lid of loanIdsInEntry) {
      // Map original loan IDs back to mirror loan IDs if viewing from the mirror company context
      if (originalToMirrorLoanId.has(lid)) {
        lid = originalToMirrorLoanId.get(lid)!;
      }
      
      if (!entriesByLoan.has(lid)) entriesByLoan.set(lid, []);
      entriesByLoan.get(lid)!.push(je);
    }
  }

  // Build loan statement entries (only those from journal entries, only affecting LR)
  const allEntries: any[] = [];
  const onlineLoansSummary: any[] = [];
  const offlineLoansSummary: any[] = [];

  for (const loanId of validLoanIds) {
    const meta = loanDataMap.get(loanId);
    if (!meta) continue;

    const loanJEs = entriesByLoan.get(loanId) || [];

    const hasDisbursement = loanJEs.some(je => 
      (je.referenceType === 'LOAN_DISBURSEMENT' || je.referenceType === 'MIRROR_LOAN_DISBURSEMENT') &&
      je.lines.some((l: any) => lrAccountIds.includes(l.accountId) && l.debitAmount > 0 && l.loanId === loanId)
    );

    if (!hasDisbursement && meta.loanAmount > 0) {
      allEntries.push({
        id: `synth-disb-${loanId}`,
        date: meta.disbursementDate || new Date(),
        referenceType: 'LOAN_DISBURSEMENT',
        referenceId: loanId,
        loanId,
        loanNumber: meta.loanNumber,
        emiNumber: undefined,
        entryNumber: 'Auto',
        createdAt: meta.disbursementDate || new Date(),
        narration: `Loan Disbursed — ${meta.loanNumber}`,
        description: `Loan Disbursed — ${meta.loanNumber}`,
        principalDisbursed: meta.loanAmount,
        principalPaid: 0,
        interestPaid: 0,
        totalPayment: null,
        lines: [
          {
            accountCode: '1200',
            accountName: toLoanGivenLabel('Loans Receivable', customer?.name || ''),
            debitAmount: meta.loanAmount,
            creditAmount: 0,
            narration: 'Loan principal disbursed (synthetic)',
          },
          {
            accountCode: '2100',
            accountName: 'Accounts Payable',
            debitAmount: 0,
            creditAmount: meta.loanAmount,
            narration: 'Funded via mirror / pending journal (synthetic)',
          }
        ]
      });
    }

    // ── Inject missing Interest Accruals (for companies without full accounting) ──
    // Use UTC end-of-today to avoid IST timezone boundary issues (IST midnight = UTC 18:30 prev day)
    const todaySynthUTC = new Date(Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth(), new Date().getUTCDate(), 23, 59, 59, 999));
    const emiList = meta.emis || meta.emiSchedules || [];
    
    for (const emi of emiList) {
      // Check if we already have a real accrual journal entry for this EMI
      const hasRealAccrual = loanJEs.some(je => {
        if (je.referenceType !== 'INTEREST_ACCRUAL' && je.referenceType !== 'INTEREST_RECLASSIFICATION') return false;
        // Match by referenceId (which is emi.id) or by narration matching EMI number
        if (je.referenceId === emi.id) return true;
        const counterpartId = emiCounterpartMap.get(emi.id);
        if (counterpartId && je.referenceId === counterpartId) return true;
        const m = je.narration?.match(/#(\d+)/);
        return m && parseInt(m[1]) === emi.installmentNumber;
      });

      let isAccrued = false;
      const emiDueDateUTC = new Date(emi.dueDate);
      if (meta.status === 'CLOSED') {
        if (meta.closedAt) {
          const emiDueDateStart = new Date(emiDueDateUTC.getFullYear(), emiDueDateUTC.getMonth(), emiDueDateUTC.getDate());
          const closedDate = new Date(meta.closedAt);
          const closedDateStart = new Date(closedDate.getFullYear(), closedDate.getMonth(), closedDate.getDate());
          isAccrued = emiDueDateStart <= closedDateStart;
        } else {
          isAccrued = emiDueDateUTC <= todaySynthUTC;
        }
      } else {
        // FIXED: use UTC end-of-day, and only include paid EMIs (not future PENDING ones)
        const isDuePassed = emiDueDateUTC <= todaySynthUTC;
        const isPaidEMI = !!(emi.paidDate && Number(emi.paidAmount) > 0);
        isAccrued = isDuePassed || isPaidEMI;
      }
      
      const effectiveInterestAmount = emi.interestAmount;
      
      if (!hasRealAccrual && isAccrued && effectiveInterestAmount > 0) {
        // Cap display date to today — never show a future-dated synthetic accrual row
        // If the EMI is paid, show the interest accrual on the actual payment date (for advance payments)
        const synthDisplayDate = emiDueDateUTC > todaySynthUTC
          ? (emi.paidDate ? new Date(emi.paidDate) : new Date())
          : emi.dueDate;
        allEntries.push({
          id: `synth-accrual-${emi.id}`,
          date: synthDisplayDate,
          referenceType: 'INTEREST_ACCRUAL',
          referenceId: emi.id,
          loanId,
          loanNumber: meta.loanNumber,
          emiNumber: emi.installmentNumber,
          entryNumber: 'Auto',
          createdAt: synthDisplayDate,
          narration: `Interest Charged — Monthly EMI #${emi.installmentNumber}`,
          description: `To-INTEREST Normal Dr. Int. (Accrued)`,
          principalDisbursed: effectiveInterestAmount,
          principalPaid: 0,
          interestPaid: 0,
          totalPayment: null,
          lines: [
            {
              accountCode: '1301',
              accountName: `Interest Receivable — ${customer?.name || ''}`,
              debitAmount: effectiveInterestAmount,
              creditAmount: 0,
              narration: 'Synthetic Accrual',
            },
            {
              accountCode: '4110',
              accountName: 'Interest Income',
              debitAmount: 0,
              creditAmount: effectiveInterestAmount,
              narration: 'Synthetic Accrual',
            }
          ]
        });
      }
    }

    for (const je of loanJEs) {
      // The line's loanId might be the original loan ID if this is a cross-company mirror loan.
      const isLineForThisLoan = (l: any) => String(l.loanId) === String(loanId) || originalToMirrorLoanId.get(String(l.loanId)) === String(loanId);

      let loanLines = je.lines.filter((l: any) => isLineForThisLoan(l));

      // Fallback for PF entries where NO line has a loanId (old DB entries before fix):
      // The JE was grouped here via referenceId, so use ALL lines for amount extraction.
      const isPFAccrualOrCollection = je.referenceType === 'PROCESSING_FEE_ACCRUAL' ||
        je.referenceType === 'PROCESSING_FEE_COLLECTION' || je.referenceType === 'PROCESSING_FEE';
      if (loanLines.length === 0 && isPFAccrualOrCollection && je.referenceId) {
        const cleanRefId = je.referenceId
          .replace(/-MIR-PF-JE$/i, '')
          .replace(/-PF-JE$/i, '')
          .replace(/-MIR-PF$/i, '')
          .replace(/-PF$/i, '');
        if (cleanRefId === loanId) {
          loanLines = je.lines;
        }
      }

      if (loanLines.length === 0) continue;

      const isPFAccrual = je.referenceType === 'PROCESSING_FEE_ACCRUAL';
      const isPFPayment = je.referenceType === 'PROCESSING_FEE_COLLECTION' || je.referenceType === 'PROCESSING_FEE';
      const isAccrual = je.referenceType === 'INTEREST_ACCRUAL' || je.referenceType === 'INTEREST_RECLASSIFICATION';
      const isPayment = je.referenceType === 'EMI_PAYMENT' || je.referenceType === 'MIRROR_EMI_PAYMENT' || je.referenceType === 'INTEREST_ONLY_PAYMENT';
      const isClose   = je.referenceType === 'PRINCIPAL_ONLY_PAYMENT' || je.referenceType === 'OFFLINE_LOAN_FORECLOSURE' || je.referenceType === 'LOAN_FORECLOSURE' || je.referenceType === 'LOSS_WRITE_OFF';
      const isDisbursement = je.referenceType === 'LOAN_DISBURSEMENT' || je.referenceType === 'MIRROR_LOAN_DISBURSEMENT';

      let principalPaid = 0;
      let principalDisbursed = 0;
      let interestPaid = 0;

      if (isPFAccrual) {
        const pfReceivableLines = loanLines.filter((l: any) => l.account?.accountCode === '1302');
        principalDisbursed = pfReceivableLines.reduce((s: number, l: any) => s + l.debitAmount, 0);
        if (principalDisbursed === 0) {
          const incomeLines = loanLines.filter((l: any) => ['4121', '4120'].includes(l.account?.accountCode || ''));
          principalDisbursed = incomeLines.reduce((s: number, l: any) => s + l.creditAmount, 0);
        }
        if (principalDisbursed === 0) {
          principalDisbursed = loanLines.reduce((s: number, l: any) => s + l.debitAmount, 0);
        }
      } else if (isPFPayment) {
        const pfReceivableLines = loanLines.filter((l: any) => l.account?.accountCode === '1302');
        interestPaid = pfReceivableLines.reduce((s: number, l: any) => s + l.creditAmount, 0);
        if (interestPaid === 0) {
          const incomeLines = loanLines.filter((l: any) => ['4121', '4120'].includes(l.account?.accountCode || ''));
          interestPaid = incomeLines.reduce((s: number, l: any) => s + l.creditAmount, 0);
        }
        if (interestPaid === 0) {
          interestPaid = loanLines.reduce((s: number, l: any) => s + l.creditAmount, 0);
        }
      } else if (isAccrual) {
        // Accruals: Debit column (principalDisbursed) represents interest charged
        const interestReceivableLines = loanLines.filter((l: any) => 
          ['1301', '1305'].includes(l.account?.accountCode || '')
        );
        principalDisbursed = interestReceivableLines.reduce((s: number, l: any) => s + l.debitAmount, 0);
        
        if (principalDisbursed === 0) {
          const interestIncomeLines = loanLines.filter((l: any) => 
            ['4110', '4100', '4001', '4002'].includes(l.account?.accountCode || '')
          );
          principalDisbursed = interestIncomeLines.reduce((s: number, l: any) => s + l.creditAmount, 0);
        }
      } else if (isPayment) {
        // Payments: Principal paid is credit to 1200/1201/1210. Interest paid is credit to 1301/1305/4110/etc.
        const principalLines = loanLines.filter((l: any) => 
          ['1200', '1201', '1210'].includes(l.account?.accountCode || '')
        );
        principalPaid = principalLines.reduce((s: number, l: any) => s + l.creditAmount, 0);

        const interestLines = loanLines.filter((l: any) => 
          ['1301', '1305', '4110', '4100', '4001', '4002'].includes(l.account?.accountCode || '')
        );
        interestPaid = interestLines.reduce((s: number, l: any) => s + l.creditAmount, 0);

        // INTEREST_ONLY_PAYMENT never reduces principal.
        // Old broken JEs incorrectly credit 1200 (Loans Receivable) instead of 1301 (Interest Receivable).
        // Detect this: if it's an IO payment and credit is only on 1200 with no interest lines, reclassify.
        if (je.referenceType === 'INTEREST_ONLY_PAYMENT' && interestPaid === 0 && principalPaid > 0) {
          interestPaid = principalPaid;
          principalPaid = 0;
        }

      } else if (isDisbursement) {
        // Disbursement: Debit column is principal disbursed
        const principalLines = loanLines.filter((l: any) => 
          ['1200', '1201', '1210'].includes(l.account?.accountCode || '')
        );
        principalDisbursed = principalLines.reduce((s: number, l: any) => s + l.debitAmount, 0);
      } else if (isClose) {
        // Close/Foreclosure: credit to 1200 = principal recovered/written off; credit to interest accounts = interest cleared
        const principalLines = loanLines.filter((l: any) =>
          ['1200', '1201', '1210'].includes(l.account?.accountCode || '')
        );
        principalPaid = principalLines.reduce((s: number, l: any) => s + l.creditAmount, 0);
        const interestLines = loanLines.filter((l: any) =>
          ['1301', '1305', '4110', '4100', '4001', '4002'].includes(l.account?.accountCode || '')
        );
        interestPaid = interestLines.reduce((s: number, l: any) => s + l.creditAmount, 0);
      } else {
        // Fallback for manual/other journal entries
        const lrLines = loanLines.filter((l: any) => 
          ['1200', '1201', '1210'].includes(l.account?.accountCode || '')
        );
        const intLines = loanLines.filter((l: any) => 
          ['1301', '1305', '4110', '4100', '4001', '4002'].includes(l.account?.accountCode || '')
        );
        principalDisbursed = lrLines.reduce((s: number, l: any) => s + l.debitAmount, 0);
        principalPaid = lrLines.reduce((s: number, l: any) => s + l.creditAmount, 0);
        interestPaid = intLines.reduce((s: number, l: any) => s + l.creditAmount, 0);
      }

      const totalPayment = (principalPaid > 0 || interestPaid > 0)
        ? principalPaid + interestPaid
        : null;

      // Determine EMI number from narration, or DB mapping (payment/offline EMI lookup)
      const emiMatch = je.narration?.match(/#(\d+)/);
      let emiNumber = emiMatch ? parseInt(emiMatch[1]) : undefined;
      if (!emiNumber && je.referenceId) {
        emiNumber = paymentToEmiNumber.get(je.referenceId) || offlineEmiIdToNumber.get(je.referenceId);
      }

      // Description: derive from referenceType and narration
      const desc = buildDescription(je.referenceType, je.narration, emiNumber, meta.loanNumber, customer?.name || '');

      allEntries.push({
        id: je.id,
        entryNumber: je.entryNumber,
        createdAt: je.createdAt,
        date: je.entryDate,
        referenceType: je.referenceType,
        referenceId: je.referenceId,
        loanId,
        loanNumber: meta.loanNumber,
        emiNumber,
        narration: je.narration,
        description: desc,
        principalDisbursed,
        principalPaid,
        interestPaid,
        totalPayment,
        // All lines of the entry for display
        lines: je.lines.map((l: any) => ({
          accountCode: l.account?.accountCode || '',
          accountName: l.account?.accountCode && LR_CODES.includes(l.account.accountCode)
            ? (l.account.accountCode === '1301'
                ? `Interest Receivable — ${customer?.name || ''}`
                : l.account.accountCode === '1305'
                  ? `Overdue Interest Receivable — ${customer?.name || ''}`
                  : l.account.accountCode === '1302'
                    ? `Processing Fee — ${customer?.name || ''}`
                    : toLoanGivenLabel('Loan Given', customer?.name || ''))
            : (l.account?.accountName || 'Account'),
          debitAmount: l.debitAmount,
          creditAmount: l.creditAmount,
          narration: l.narration,
        })),
      });
    }

    // ── Synthetic "Loan Closed" entry for closed loans with no close journal entry ──
    // This handles legacy closures that happened before loanId tagging was added.
    if (meta.status === 'CLOSED') {
      const hasCloseJE = loanJEs.some(je =>
        je.referenceType === 'PRINCIPAL_ONLY_PAYMENT' ||
        je.referenceType === 'OFFLINE_LOAN_FORECLOSURE' ||
        je.referenceType === 'LOAN_FORECLOSURE' ||
        je.referenceType === 'LOSS_WRITE_OFF'
      );
      if (!hasCloseJE) {
        // Use EMI data to compute what was settled on close
        const emiList2 = meta.emis || meta.emiSchedules || [];
        const closedEMIs = emiList2.filter((e: any) => e.paymentStatus === 'PAID' || e.paymentStatus === 'WAIVED');
        const closePrincipal = closedEMIs.reduce((s: number, e: any) => s + (Number(e.paidPrincipal) || 0), 0);
        const closeInterest  = closedEMIs.reduce((s: number, e: any) => s + (Number(e.paidInterest)  || 0), 0);
        // Find latest paidDate or closedAt
        const latestPaidDates = closedEMIs.map((e: any) => e.paidDate ? new Date(e.paidDate) : null).filter(Boolean) as Date[];
        const closeDate = latestPaidDates.length > 0 ? new Date(Math.max(...latestPaidDates.map(d => d.getTime()))) : new Date();
        if (closePrincipal > 0 || closeInterest > 0) {
          allEntries.push({
            id: `synth-close-${loanId}`,
            date: closeDate,
            referenceType: 'LOAN_CLOSURE',
            referenceId: loanId,
            loanId,
            loanNumber: meta.loanNumber,
            emiNumber: undefined,
            entryNumber: 'Auto',
            createdAt: closeDate,
            narration: `Loan Closed — ${meta.loanNumber}`,
            description: `Loan Closed (Foreclosure / Full Settlement) — ${meta.loanNumber}`,
            principalDisbursed: 0,
            principalPaid: closePrincipal,
            interestPaid: closeInterest,
            totalPayment: closePrincipal + closeInterest,
            lines: [
              { accountCode: '1200', accountName: `Loan Given — ${customer?.name || ''}`, debitAmount: 0, creditAmount: closePrincipal, narration: 'Principal settled on loan close (synthetic)' },
              ...(closeInterest > 0 ? [{ accountCode: '1301', accountName: `Interest — ${customer?.name || ''}`, debitAmount: 0, creditAmount: closeInterest, narration: 'Interest settled/waived on close (synthetic)' }] : [])
            ]
          });
        }
      }
    }

    // Compute outstanding for this loan from its journal entries
    const loanJEsAll = entriesByLoan.get(loanId) || [];
    const isLineForThisLoanSummary = (l: any) => String(l.loanId) === String(loanId) || originalToMirrorLoanId.get(String(l.loanId)) === String(loanId);

    let totalDisbursed = loanJEsAll.reduce((s, je) => {
      const lrLines = je.lines.filter((l: any) => 
        ['1200', '1201', '1210'].includes(l.account?.accountCode || '') && isLineForThisLoanSummary(l)
      );
      return s + lrLines.reduce((ss: number, l: any) => ss + l.debitAmount, 0);
    }, 0);

    if (totalDisbursed === 0 && meta.loanAmount > 0) {
      totalDisbursed = meta.loanAmount;
    }

    const totalRepaid = loanJEsAll.reduce((s, je) => {
      // INTEREST_ONLY_PAYMENT never repays principal — exclude from principal sum.
      // (Old broken JEs had Cr 1200 in IO payment which would incorrectly reduce outstanding principal)
      const isAnyPayment = je.referenceType === 'EMI_PAYMENT' || je.referenceType === 'MIRROR_EMI_PAYMENT' ||
        je.referenceType === 'PRINCIPAL_ONLY_PAYMENT' ||
        je.referenceType === 'OFFLINE_LOAN_FORECLOSURE' || je.referenceType === 'LOAN_FORECLOSURE' ||
        je.referenceType === 'LOSS_WRITE_OFF';
      if (!isAnyPayment) return s;
      const lrLines = je.lines.filter((l: any) =>
        ['1200', '1201', '1210'].includes(l.account?.accountCode || '') && isLineForThisLoanSummary(l)
      );
      return s + lrLines.reduce((ss: number, l: any) => ss + l.creditAmount, 0);
    }, 0);

    const totalInterestCollected = loanJEsAll.reduce((s, je) => {
      const isAnyPayment = je.referenceType === 'EMI_PAYMENT' || je.referenceType === 'MIRROR_EMI_PAYMENT' ||
        je.referenceType === 'INTEREST_ONLY_PAYMENT' || je.referenceType === 'PRINCIPAL_ONLY_PAYMENT' ||
        je.referenceType === 'OFFLINE_LOAN_FORECLOSURE' || je.referenceType === 'LOAN_FORECLOSURE' ||
        je.referenceType === 'LOSS_WRITE_OFF';
      if (!isAnyPayment) return s;
      const iLines = je.lines.filter((l: any) =>
        ['1301', '1305', '4110', '4100', '4001', '4002'].includes(l.account?.accountCode || '') && isLineForThisLoanSummary(l)
      );
      let interestAmt = iLines.reduce((ss: number, l: any) => ss + l.creditAmount, 0);
      // Old broken IO payment JEs credit 1200 instead of 1301.
      // Since IO never repays principal, any Cr 1200 in an IO payment is actually interest collected.
      if (je.referenceType === 'INTEREST_ONLY_PAYMENT' && interestAmt === 0) {
        const lrLines = je.lines.filter((l: any) =>
          ['1200', '1201', '1210'].includes(l.account?.accountCode || '') && isLineForThisLoanSummary(l)
        );
        interestAmt = lrLines.reduce((ss: number, l: any) => ss + l.creditAmount, 0);
      }
      return s + interestAmt;
    }, 0);

    const outstanding = Math.max(0, totalDisbursed - totalRepaid);
    const totalPaid = totalRepaid + totalInterestCollected;

    const summary = {
      id: loanId,
      loanNumber: meta.loanNumber,
      type: meta.loanType,
      status: meta.status,
      amount: meta.loanAmount || totalDisbursed,
      disbursementDate: meta.disbursementDate,
      interestRate: meta.interestRate,
      tenure: meta.tenure,
      isMirror: meta.isMirror,
      companyName: meta.companyName,
      outstanding,
      totalPaid,
      totalInterestPaid: totalInterestCollected,
      totalPrincipalPaid: totalRepaid,
    };

    if (meta.loanType === 'ONLINE') onlineLoansSummary.push(summary);
    else offlineLoansSummary.push(summary);
  }

  allEntries.sort((a, b) => {
    const ORDER: Record<string, number> = {
      PROCESSING_FEE_ACCRUAL: 1,
      PROCESSING_FEE_COLLECTION: 2, PROCESSING_FEE: 2,
      LOAN_DISBURSEMENT: 3, MIRROR_LOAN_DISBURSEMENT: 3,
      INTEREST_ACCRUAL: 4, INTEREST_RECLASSIFICATION: 4,
      EMI_PAYMENT: 5, MIRROR_EMI_PAYMENT: 5, INTEREST_ONLY_PAYMENT: 5, PARTIAL_EMI_PAYMENT: 5,
      PRINCIPAL_ONLY_PAYMENT: 6, OFFLINE_LOAN_FORECLOSURE: 7, LOAN_FORECLOSURE: 7, LOSS_WRITE_OFF: 7
    };

    const dateA = new Date(a.date);
    const dateB = new Date(b.date);

    const isSameDay = dateA.getFullYear() === dateB.getFullYear() &&
                      dateA.getMonth() === dateB.getMonth() &&
                      dateA.getDate() === dateB.getDate();

    if (isSameDay) {
      const entryA = a.entryNumber;
      const entryB = b.entryNumber;
      if (entryA && entryB && entryA.startsWith('JE') && entryB.startsWith('JE') && entryA !== entryB) {
        const cmp = entryA.localeCompare(entryB, undefined, { numeric: true });
        if (cmp !== 0) return cmp;
      }
    }

    const timeA = dateA.getTime();
    const timeB = dateB.getTime();

    if (timeA !== timeB) {
      return timeA - timeB;
    }

    if (a.entryNumber && b.entryNumber && a.entryNumber.startsWith('JE') && b.entryNumber.startsWith('JE') && a.entryNumber !== b.entryNumber) {
      const cmp = a.entryNumber.localeCompare(b.entryNumber, undefined, { numeric: true });
      if (cmp !== 0) return cmp;
    }

    const createA = a.createdAt ? new Date(a.createdAt).getTime() : 0;
    const createB = b.createdAt ? new Date(b.createdAt).getTime() : 0;
    if (createA !== createB) {
      return createA - createB;
    }

    const emiA = a.emiNumber;
    const emiB = b.emiNumber;
    if (emiA !== undefined && emiB !== undefined && emiA !== emiB) {
      return emiA - emiB;
    }

    const oA = ORDER[a.referenceType] ?? 9;
    const oB = ORDER[b.referenceType] ?? 9;
    if (oA !== oB) return oA - oB;

    const idA = a.id || '';
    const idB = b.id || '';
    return idA.localeCompare(idB);
  });

  const totalOutstanding = [...onlineLoansSummary, ...offlineLoansSummary]
    .reduce((s, l) => s + l.outstanding, 0);

  return NextResponse.json({
    success: true,
    customerSummary: {
      ...customer,
      onlineLoans: onlineLoansSummary,
      offlineLoans: offlineLoansSummary,
      totalOutstanding,
    },
    entries: allEntries,
    source: 'journal_entries',
  });
}

function buildDescription(refType: string, narration: string, emiNumber: number | undefined, loanNumber: string, customerName: string): string {
  const t = (refType || '').toUpperCase();
  const name = customerName || 'Customer';
  if (t === 'LOAN_DISBURSEMENT' || t === 'MIRROR_LOAN_DISBURSEMENT') return `Loan Given - ${name}`;
  if (t === 'EMI_PAYMENT' || t === 'MIRROR_EMI_PAYMENT') return `Loan EMI - ${name} (P+I)`;
  if (t === 'INTEREST_ONLY_PAYMENT') return emiNumber ? `IO EMI #${emiNumber} - ${name}` : `Interest Only - ${name}`;
  if (t === 'PARTIAL_EMI_PAYMENT') return `EMI #${emiNumber || '?'} - Partial Payment - ${name}`;
  if (t === 'PENALTY_COLLECTION') return `Late Penalty - ${name}`;
  if (t === 'EXTRA_EMI_PAYMENT') return `Extra EMI #${emiNumber || ''} - ${name}`;
  if (t === 'PROCESSING_FEE_ACCRUAL') return `Processing Fee Accrued — ${name}`;
  if (t === 'PROCESSING_FEE_COLLECTION' || t === 'PROCESSING_FEE') return `Processing Fee Received — ${name}`;
  return narration?.replace(/\[.*?\]/g, '').replace(/mirror/gi, '').trim() || refType?.replace(/_/g, ' ') || 'Transaction';
}

// ─────────────────────────────────────────────────────────────────────────────
// FALLBACK personal ledger (EMI-based, but NO processing fee)
// ─────────────────────────────────────────────────────────────────────────────
async function getPersonalLedgerFallback(customerId: string, companyId: string | null, customer: any, onlineLoans: any[], offlineLoans: any[], mirroredIds: Set<string>) {
  const allEntries: any[] = [];
  const onlineLoansSummary: any[] = [];
  const offlineLoansSummary: any[] = [];

  for (const loan of onlineLoans) {
    const fullLoan = await db.loanApplication.findUnique({
      where: { id: loan.id },
      include: { sessionForm: true, emiSchedules: { orderBy: { installmentNumber: 'asc' } } }
    });
    if (!fullLoan) continue;

    const loanAmount = fullLoan.sessionForm?.approvedAmount || fullLoan.requestedAmount || 0;
    const isMirror = mirroredIds.has(loan.id);
    const receivableLabel = `Loans Receivable — ${customer?.name || ''}`;

    if (fullLoan.disbursedAt) {
      allEntries.push({
        id: `disb-${loan.id}`, date: fullLoan.disbursedAt, referenceType: 'LOAN_DISBURSEMENT',
        loanId: loan.id, loanNumber: loan.applicationNo,
        entryNumber: 'Auto',
        createdAt: fullLoan.disbursedAt,
        description: `Loan Given - ${customer?.name || 'Customer'}`,
        principalDisbursed: loanAmount, principalPaid: 0, interestPaid: 0, totalPayment: null,
        lines: [
          { accountCode: '1200', accountName: receivableLabel, debitAmount: loanAmount, creditAmount: 0 },
          { accountCode: '1102', accountName: 'Bank Account', debitAmount: 0, creditAmount: loanAmount }
        ]
      });
    }

    // NOTE: Processing Fee is intentionally EXCLUDED — it does not touch Loans Receivable
    // Only EMI entries (which reduce the Loans Receivable balance)

    let totalPrincipalPaid = 0, totalInterestPaid = 0, totalInterestAccrued = 0;
    // Use UTC end-of-today to avoid IST timezone boundary issues
    const todayUTC = new Date(Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth(), new Date().getUTCDate(), 23, 59, 59, 999));
    for (const emi of (fullLoan.emiSchedules || [])) {
      // Only show synthetic accrual if: EMI due date has passed (UTC) OR EMI is paid
      // NEVER show future-dated synthetic accruals for PENDING (unpaid) EMIs
      const dueDateUTC = new Date(emi.dueDate);
      const isDuePassed = dueDateUTC <= todayUTC;
      const isPaid = !!(emi.paidDate && emi.paidAmount > 0);
      const isAccrued = isDuePassed || isPaid;
      if (isAccrued && emi.interestAmount > 0) {
        totalInterestAccrued += emi.interestAmount;
        // Use dueDate as the synthetic accrual date — but cap to today if it's future
        // If the EMI is paid, show the interest accrual on the actual payment date
        const accrualDisplayDate = dueDateUTC > todayUTC
          ? (emi.paidDate ? new Date(emi.paidDate) : new Date())
          : emi.dueDate;
        allEntries.push({
          id: `accrual-${emi.id}`, date: accrualDisplayDate,
          referenceType: 'INTEREST_ACCRUAL', loanId: loan.id, loanNumber: loan.applicationNo,
          emiNumber: emi.installmentNumber,
          entryNumber: 'Auto',
          createdAt: accrualDisplayDate,
          description: `Interest Charged — Monthly EMI #${emi.installmentNumber}`,
          principalDisbursed: emi.interestAmount, principalPaid: 0, interestPaid: 0, totalPayment: null,
          lines: [
            { accountCode: '1301', accountName: `Interest Receivable — ${customer?.name || ''}`, debitAmount: emi.interestAmount, creditAmount: 0 },
            { accountCode: '4110', accountName: 'Interest Income', debitAmount: 0, creditAmount: emi.interestAmount }
          ]
        });
      }

      if (!emi.paidDate || emi.paidAmount <= 0) continue;
      const pp = emi.paidPrincipal || 0;
      const ip = emi.paidInterest  || 0;
      totalPrincipalPaid += pp;
      totalInterestPaid  += ip;

      allEntries.push({
        id: `emi-${emi.id}`, date: emi.paidDate,
        referenceType: emi.isInterestOnly ? 'INTEREST_ONLY_PAYMENT' : 'EMI_PAYMENT',
        loanId: loan.id, loanNumber: loan.applicationNo,
        emiNumber: emi.installmentNumber,
        entryNumber: 'Auto',
        createdAt: emi.paidDate,
        description: emi.isInterestOnly ? `IO EMI #${emi.installmentNumber} - ${customer?.name || 'Customer'}` : `Loan EMI - ${customer?.name || 'Customer'} (P+I)`,
        principalDisbursed: 0, principalPaid: pp, interestPaid: ip, totalPayment: pp + ip,
        lines: [
          { accountCode: '1102', accountName: 'Bank/Cash', debitAmount: emi.paidAmount, creditAmount: 0 },
          ...(pp > 0 ? [{ accountCode: '1200', accountName: receivableLabel, debitAmount: 0, creditAmount: pp }] : []),
          ...(ip > 0 ? [{ accountCode: '1301', accountName: `Interest Receivable — ${customer?.name || ''}`,  debitAmount: 0, creditAmount: ip }] : []),
        ]
      });
    }

    onlineLoansSummary.push({
      id: loan.id, loanNumber: loan.applicationNo, type: 'ONLINE',
      status: loan.status, amount: loanAmount, disbursementDate: fullLoan.disbursedAt,
      interestRate: fullLoan.sessionForm?.interestRate || 0,
      tenure: fullLoan.sessionForm?.tenure || 0, isMirror,
      outstanding: Math.max(0, (loanAmount + totalInterestAccrued) - (totalPrincipalPaid + totalInterestPaid)),
      totalPaid: totalPrincipalPaid + totalInterestPaid,
      totalInterestPaid, totalPrincipalPaid,
    });
  }

  for (const loan of offlineLoans) {
    const fullLoan = await db.offlineLoan.findUnique({
      where: { id: loan.id },
      include: { emis: { orderBy: { dueDate: 'asc' } } }
    });
    if (!fullLoan) continue;
    const receivableLabel = `Loans Receivable — ${customer?.name || ''}`;

    if (fullLoan.disbursementDate) {
      allEntries.push({
        id: `offline-disb-${loan.id}`, date: fullLoan.disbursementDate,
        referenceType: 'LOAN_DISBURSEMENT', loanId: loan.id, loanNumber: loan.loanNumber,
        entryNumber: 'Auto',
        createdAt: fullLoan.disbursementDate,
        description: `Loan Disbursed — ${loan.loanNumber}`,
        principalDisbursed: fullLoan.loanAmount, principalPaid: 0, interestPaid: 0, totalPayment: null,
        lines: [
          { accountCode: '1200', accountName: receivableLabel, debitAmount: fullLoan.loanAmount, creditAmount: 0 },
          { accountCode: '1101', accountName: 'Cash/Bank', debitAmount: 0, creditAmount: fullLoan.loanAmount }
        ]
      });
    }

    let totalPrincipalPaid = 0, totalInterestPaid = 0, totalInterestAccrued = 0;
    // Use UTC end-of-today to avoid IST timezone boundary issues
    const todayUTC2 = new Date(Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth(), new Date().getUTCDate(), 23, 59, 59, 999));
    for (const emi of (fullLoan.emis || [])) {
      // Only show synthetic accrual if: EMI due date has passed (UTC) OR EMI is paid
      // NEVER show future-dated synthetic accruals for PENDING (unpaid) EMIs
      const dueDateUTC2 = new Date(emi.dueDate);
      const isDuePassed2 = dueDateUTC2 <= todayUTC2;
      const isPaid2 = !!(emi.paidDate && emi.paidAmount > 0);
      const isAccrued = isDuePassed2 || isPaid2;
      if (isAccrued && emi.interestAmount > 0) {
        totalInterestAccrued += emi.interestAmount;
        // Cap display date to today if EMI due date is future
        // If the EMI is paid, show the interest accrual on the actual payment date
        const accrualDisplayDate2 = dueDateUTC2 > todayUTC2
          ? (emi.paidDate ? new Date(emi.paidDate) : new Date())
          : emi.dueDate;
        allEntries.push({
          id: `offline-accrual-${emi.id}`, date: accrualDisplayDate2,
          referenceType: 'INTEREST_ACCRUAL', loanId: loan.id, loanNumber: loan.loanNumber,
          emiNumber: emi.installmentNumber,
          entryNumber: 'Auto',
          createdAt: accrualDisplayDate2,
          description: `Interest Charged — Monthly EMI #${emi.installmentNumber}`,
          principalDisbursed: emi.interestAmount, principalPaid: 0, interestPaid: 0, totalPayment: null,
          lines: [
            { accountCode: '1301', accountName: `Interest Receivable — ${customer?.name || ''}`, debitAmount: emi.interestAmount, creditAmount: 0 },
            { accountCode: '4110', accountName: 'Interest Income', debitAmount: 0, creditAmount: emi.interestAmount }
          ]
        });
      }

      if (!emi.paidDate || emi.paidAmount <= 0) continue;
      const pp = emi.paidPrincipal || 0;
      const ip = emi.paidInterest  || 0;
      totalPrincipalPaid += pp;
      totalInterestPaid  += ip;
      allEntries.push({
        id: `offline-emi-${emi.id}`, date: emi.paidDate,
        referenceType: 'EMI_PAYMENT', loanId: loan.id, loanNumber: loan.loanNumber,
        emiNumber: emi.installmentNumber,
        entryNumber: 'Auto',
        createdAt: emi.paidDate,
        description: `Monthly EMI #${emi.installmentNumber}`,
        principalDisbursed: 0, principalPaid: pp, interestPaid: ip, totalPayment: pp + ip,
        lines: [
          { accountCode: '1101', accountName: 'Cash/Bank', debitAmount: emi.paidAmount, creditAmount: 0 },
          ...(pp > 0 ? [{ accountCode: '1200', accountName: receivableLabel, debitAmount: 0, creditAmount: pp }] : []),
          ...(ip > 0 ? [{ accountCode: '1301', accountName: `Interest Receivable — ${customer?.name || ''}`,  debitAmount: 0, creditAmount: ip }] : []),
        ]
      });
    }

    offlineLoansSummary.push({
      id: loan.id, loanNumber: loan.loanNumber, type: 'OFFLINE',
      status: loan.status, amount: fullLoan.loanAmount,
      disbursementDate: fullLoan.disbursementDate,
      interestRate: fullLoan.interestRate || 0, tenure: fullLoan.tenure || 0, isMirror: false,
      outstanding: Math.max(0, (fullLoan.loanAmount + totalInterestAccrued) - (totalPrincipalPaid + totalInterestPaid)),
      totalPaid: totalPrincipalPaid + totalInterestPaid,
      totalInterestPaid, totalPrincipalPaid,
    });
  }

  allEntries.sort((a, b) => {
    const ORDER: Record<string, number> = {
      PROCESSING_FEE_ACCRUAL: 1,
      PROCESSING_FEE_COLLECTION: 2, PROCESSING_FEE: 2,
      LOAN_DISBURSEMENT: 3, MIRROR_LOAN_DISBURSEMENT: 3,
      INTEREST_ACCRUAL: 4, INTEREST_RECLASSIFICATION: 4,
      EMI_PAYMENT: 5, MIRROR_EMI_PAYMENT: 5, INTEREST_ONLY_PAYMENT: 5, PARTIAL_EMI_PAYMENT: 5,
      PRINCIPAL_ONLY_PAYMENT: 6, OFFLINE_LOAN_FORECLOSURE: 7, LOAN_FORECLOSURE: 7, LOSS_WRITE_OFF: 7
    };

    const dateA = new Date(a.date);
    const dateB = new Date(b.date);

    const isSameDay = dateA.getFullYear() === dateB.getFullYear() &&
                      dateA.getMonth() === dateB.getMonth() &&
                      dateA.getDate() === dateB.getDate();

    if (isSameDay) {
      const entryA = a.entryNumber;
      const entryB = b.entryNumber;
      if (entryA && entryB && entryA.startsWith('JE') && entryB.startsWith('JE') && entryA !== entryB) {
        const cmp = entryA.localeCompare(entryB, undefined, { numeric: true });
        if (cmp !== 0) return cmp;
      }
    }

    const timeA = dateA.getTime();
    const timeB = dateB.getTime();

    if (timeA !== timeB) {
      return timeA - timeB;
    }

    if (a.entryNumber && b.entryNumber && a.entryNumber.startsWith('JE') && b.entryNumber.startsWith('JE') && a.entryNumber !== b.entryNumber) {
      const cmp = a.entryNumber.localeCompare(b.entryNumber, undefined, { numeric: true });
      if (cmp !== 0) return cmp;
    }

    const createA = a.createdAt ? new Date(a.createdAt).getTime() : 0;
    const createB = b.createdAt ? new Date(b.createdAt).getTime() : 0;
    if (createA !== createB) {
      return createA - createB;
    }

    const emiA = a.emiNumber;
    const emiB = b.emiNumber;
    if (emiA !== undefined && emiB !== undefined && emiA !== emiB) {
      return emiA - emiB;
    }

    const oA = ORDER[a.referenceType] ?? 9;
    const oB = ORDER[b.referenceType] ?? 9;
    if (oA !== oB) return oA - oB;

    const idA = a.id || '';
    const idB = b.id || '';
    return idA.localeCompare(idB);
  });
  const totalOutstanding = [...onlineLoansSummary, ...offlineLoansSummary].reduce((s, l) => s + l.outstanding, 0);

  return NextResponse.json({
    success: true,
    customerSummary: {
      ...customer,
      onlineLoans: onlineLoansSummary,
      offlineLoans: offlineLoansSummary,
      totalOutstanding,
    },
    entries: allEntries,
    source: 'emi_fallback',
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// Single loan ledger
// ─────────────────────────────────────────────────────────────────────────────
async function getSingleLoanLedger(loanId: string, companyId: string | null) {
  let loan = await db.loanApplication.findUnique({
    where: { id: loanId },
    include: {
      customer:     { select: { id: true, name: true, phone: true } },
      company:      { select: { id: true, name: true } },
      sessionForm:  true,
      emiSchedules: { orderBy: { installmentNumber: 'asc' } },
    }
  });

  let offlineLoan: any = null;

  if (!loan) {
    offlineLoan = await db.offlineLoan.findUnique({
      where: { id: loanId },
      include: {
        customer: { select: { id: true, name: true, phone: true } },
        company:  { select: { id: true, name: true } },
        emis:     { orderBy: { installmentNumber: 'asc' } }
      }
    });

    if (!offlineLoan) {
      return NextResponse.json({ success: false, error: 'Loan not found' }, { status: 404 });
    }
  }

  const effectiveCompanyId = loan ? loan.companyId : offlineLoan.companyId;
  const applicationNo = loan ? loan.applicationNo : offlineLoan.loanNumber;
  const customer = loan ? loan.customer : (offlineLoan.customer || (offlineLoan.customerName ? { id: `offline_${offlineLoan.id}`, name: offlineLoan.customerName, phone: offlineLoan.customerPhone } : null));
  const company = loan ? loan.company : offlineLoan.company;
  const disbursedAt = loan ? loan.disbursedAt : offlineLoan.disbursementDate;
  const loanAmount = loan ? (loan.sessionForm?.approvedAmount || loan.requestedAmount || 0) : offlineLoan.loanAmount;

  const lrAccountIds = await getLRAccountIds(companyId || effectiveCompanyId);
  const targetCompanyId = companyId || effectiveCompanyId;

  // Find mirror mapping if any
  const mirrorMapping = await db.mirrorLoanMapping.findFirst({
    where: {
      OR: [
        { originalLoanId: loanId },
        { mirrorLoanId: loanId }
      ]
    }
  });

  const queryLoanIds = [loanId];
  if (mirrorMapping) {
    if (mirrorMapping.originalLoanId) queryLoanIds.push(mirrorMapping.originalLoanId);
    if (mirrorMapping.mirrorLoanId) queryLoanIds.push(mirrorMapping.mirrorLoanId);
  }

  // Fetch standard journal entries in the target company
  const standardEntries = lrAccountIds.length > 0 && targetCompanyId
    ? await db.journalEntry.findMany({
        where: {
          isReversed: false,
          companyId: targetCompanyId,
          lines: { some: { accountId: { in: lrAccountIds }, loanId: { in: queryLoanIds } } }
        },
        include: { lines: { include: { account: true } } },
        orderBy: { entryDate: 'asc' }
      })
    : [];

  // Fetch interest accrual and reclassification entries globally
  const accrualEntries = await db.journalEntry.findMany({
    where: {
      isReversed: false,
      referenceType: { in: ['INTEREST_ACCRUAL', 'INTEREST_RECLASSIFICATION'] },
      lines: { some: { loanId: { in: queryLoanIds } } }
    },
    include: { lines: { include: { account: true } } },
    orderBy: { entryDate: 'asc' }
  });

  // Fetch installment numbers for payments and offline EMIs to map je.referenceId to emiNumber
  const paymentToEmiNumber = new Map<string, number>();
  const offlineEmiIdToNumber = new Map<string, number>();

  if (queryLoanIds.length > 0) {
    const paymentsForLedger = await db.payment.findMany({
      where: { loanApplicationId: { in: queryLoanIds } },
      select: { id: true, emiSchedule: { select: { installmentNumber: true } } }
    });
    for (const p of paymentsForLedger) {
      if (p.emiSchedule?.installmentNumber) {
        paymentToEmiNumber.set(p.id, p.emiSchedule.installmentNumber);
      }
    }

    const offlineEmisForLedger = await db.offlineLoanEMI.findMany({
      where: { offlineLoanId: { in: queryLoanIds } },
      select: { id: true, installmentNumber: true }
    });
    for (const e of offlineEmisForLedger) {
      offlineEmiIdToNumber.set(e.id, e.installmentNumber);
    }
  }

  // Merge and sort
  const allJEs = [...standardEntries, ...accrualEntries];
  const uniqueJEs = Array.from(new Map(allJEs.map(j => [j.id, j])).values());
  uniqueJEs.sort((a, b) => new Date(a.entryDate).getTime() - new Date(b.entryDate).getTime());

  const hasDisbursement = uniqueJEs.some(je => 
    (je.referenceType === 'LOAN_DISBURSEMENT' || je.referenceType === 'MIRROR_LOAN_DISBURSEMENT') &&
    je.lines.some((l: any) => lrAccountIds.includes(l.accountId) && l.debitAmount > 0 && queryLoanIds.includes(l.loanId))
  );

  const mappedEntries = uniqueJEs.map(je => {
    // Determine EMI number from narration, or DB mapping (payment/offline EMI lookup)
    const emiMatch = je.narration?.match(/#(\d+)/);
    let emiNumber = emiMatch ? parseInt(emiMatch[1]) : undefined;
    if (!emiNumber && je.referenceId) {
      emiNumber = paymentToEmiNumber.get(je.referenceId) || offlineEmiIdToNumber.get(je.referenceId);
    }

    return {
      id: je.id,
      entryNumber: je.entryNumber,
      createdAt: je.createdAt,
      date: je.entryDate,
      referenceType: je.referenceType,
      narration: je.narration,
      loanId,
      loanNumber: applicationNo,
      emiNumber,
      lines: je.lines.map(l => ({
        accountCode: l.account?.accountCode,
        accountName: l.account?.accountCode && LR_CODES.includes(l.account.accountCode)
          ? (l.account.accountCode === '1301'
              ? `Interest Receivable — ${customer?.name || ''}`
              : l.account.accountCode === '1305'
                ? `Overdue Interest Receivable — ${customer?.name || ''}`
                : l.account.accountCode === '1302'
                  ? `Processing Fee — ${customer?.name || ''}`
                  : `Loans Receivable — ${customer?.name || ''}`)
          : l.account?.accountName,
        debitAmount: l.debitAmount,
        creditAmount: l.creditAmount,
      }))
    };
  });

  if (!hasDisbursement && loanAmount > 0) {
    mappedEntries.unshift({
      id: `synth-disb-${loanId}`,
      date: disbursedAt || new Date(),
      referenceType: 'LOAN_DISBURSEMENT',
      entryNumber: 'Auto',
      createdAt: disbursedAt || new Date(),
      narration: `Loan Disbursed — ${applicationNo}`,
      loanId,
      loanNumber: applicationNo,
      emiNumber: undefined,
      lines: [
        {
          accountCode: '1200',
          accountName: `Loans Receivable — ${customer?.name || ''}`,
          debitAmount: loanAmount,
          creditAmount: 0,
        },
        {
          accountCode: '2100',
          accountName: 'Accounts Payable',
          debitAmount: 0,
          creditAmount: loanAmount,
        }
      ]
    });
  }

  mappedEntries.sort((a: any, b: any) => {
    const ORDER: Record<string, number> = {
      PROCESSING_FEE_ACCRUAL: 1,
      PROCESSING_FEE_COLLECTION: 2, PROCESSING_FEE: 2,
      LOAN_DISBURSEMENT: 3, MIRROR_LOAN_DISBURSEMENT: 3,
      INTEREST_ACCRUAL: 4, INTEREST_RECLASSIFICATION: 4,
      EMI_PAYMENT: 5, MIRROR_EMI_PAYMENT: 5, INTEREST_ONLY_PAYMENT: 5, PARTIAL_EMI_PAYMENT: 5,
      PRINCIPAL_ONLY_PAYMENT: 6, OFFLINE_LOAN_FORECLOSURE: 7, LOAN_FORECLOSURE: 7, LOSS_WRITE_OFF: 7
    };

    const dateA = new Date(a.date);
    const dateB = new Date(b.date);

    const isSameDay = dateA.getFullYear() === dateB.getFullYear() &&
                      dateA.getMonth() === dateB.getMonth() &&
                      dateA.getDate() === dateB.getDate();

    if (isSameDay) {
      const entryA = a.entryNumber;
      const entryB = b.entryNumber;
      if (entryA && entryB && entryA.startsWith('JE') && entryB.startsWith('JE') && entryA !== entryB) {
        const cmp = entryA.localeCompare(entryB, undefined, { numeric: true });
        if (cmp !== 0) return cmp;
      }
    }

    const timeA = dateA.getTime();
    const timeB = dateB.getTime();

    if (timeA !== timeB) {
      return timeA - timeB;
    }

    if (a.entryNumber && b.entryNumber && a.entryNumber.startsWith('JE') && b.entryNumber.startsWith('JE') && a.entryNumber !== b.entryNumber) {
      const cmp = a.entryNumber.localeCompare(b.entryNumber, undefined, { numeric: true });
      if (cmp !== 0) return cmp;
    }

    const createA = a.createdAt ? new Date(a.createdAt).getTime() : 0;
    const createB = b.createdAt ? new Date(b.createdAt).getTime() : 0;
    if (createA !== createB) {
      return createA - createB;
    }

    const matchA = a.narration?.match(/#(\d+)/);
    const matchB = b.narration?.match(/#(\d+)/);
    const emiA = matchA ? parseInt(matchA[1]) : (a.emiNumber ?? undefined);
    const emiB = matchB ? parseInt(matchB[1]) : (b.emiNumber ?? undefined);
    if (emiA !== undefined && emiB !== undefined && emiA !== emiB) {
      return emiA - emiB;
    }

    const oA = ORDER[a.referenceType] ?? 9;
    const oB = ORDER[b.referenceType] ?? 9;
    if (oA !== oB) return oA - oB;

    const idA = a.id || '';
    const idB = b.id || '';
    return idA.localeCompare(idB);
  });

  return NextResponse.json({
    success: true,
    loanSummary: { id: loanId, loanNumber: applicationNo, customer, company },
    entries: mappedEntries,
    source: (uniqueJEs.length > 0 || !hasDisbursement) ? 'journal_entries' : 'no_data',
  });
}

